# -*- coding: utf-8 -*-
# WgIme-Pure 单文件版 (项目模块 + 插件 + comtypes/uiautomation 内嵌). 免安装, 零 .NET, 零 pip.
import sys, types, os, base64
MODULES = {'win': '# -*- coding: utf-8 -*-\n"""win.py — 纯 ctypes Win32 层 (无 .NET): SendInput UNICODE 注入 / 光标跟随 / 剪贴板"""\nimport ctypes\nimport ctypes.wintypes as w\nimport os\n\nuser32 = ctypes.windll.user32\nkernel32 = ctypes.windll.kernel32\ngdi32 = ctypes.windll.gdi32\n\nMAGIC = 0x5747494D      # \'WGIM\': 自家注入事件的 dwExtraInfo 标记\nuser32.SendInput.restype = w.UINT\nuser32.SendInput.argtypes = [w.UINT, ctypes.c_void_p, ctypes.c_int]\n\n\n# ---------- SendInput (UNICODE) ----------\nclass KEYBDINPUT(ctypes.Structure):\n    _fields_ = [(\'wVk\', w.WORD), (\'wScan\', w.WORD), (\'dwFlags\', w.DWORD),\n                (\'time\', w.DWORD), (\'dwExtraInfo\', ctypes.c_ssize_t)]\n\n\nclass MOUSEINPUT(ctypes.Structure):\n    _fields_ = [(\'dx\', ctypes.c_long), (\'dy\', ctypes.c_long), (\'mouseData\', w.DWORD),\n                (\'dwFlags\', w.DWORD), (\'time\', w.DWORD), (\'dwExtraInfo\', ctypes.c_ssize_t)]\n\n\nclass HARDWAREINPUT(ctypes.Structure):\n    _fields_ = [(\'uMsg\', w.DWORD), (\'wParamL\', w.WORD), (\'wParamH\', w.WORD)]\n\n\nclass _U(ctypes.Union):\n    _fields_ = [(\'mi\', MOUSEINPUT), (\'ki\', KEYBDINPUT), (\'hi\', HARDWAREINPUT)]\n\n\nclass INPUT(ctypes.Structure):\n    _fields_ = [(\'type\', w.DWORD), (\'u\', _U)]\n\n\ndef send_unicode(text, magic=MAGIC):\n    """per-char sendunicode; 按 UTF-16 码元注入(支持 astral/emoji 代理对, 不再截断); return count sent."""\n    text = text or \'\'\n    units = text.encode(\'utf-16-le\', \'surrogatepass\')   # 每 2 字节一个 UTF-16 码元\n    nunits = len(units) // 2\n    n = nunits * 2\n    if n == 0:\n        return 0\n    arr = (INPUT * n)()\n    for i in range(nunits):\n        code = units[2 * i] | (units[2 * i + 1] << 8)\n        lo = 2 * i\n        arr[lo].type = 1\n        arr[lo].u.ki.wScan = code\n        arr[lo].u.ki.dwFlags = 0x4                                   # KEYEVENTF_UNICODE down\n        arr[lo + 1].type = 1\n        arr[lo + 1].u.ki.wScan = code\n        arr[lo + 1].u.ki.dwFlags = 0x4 | 0x2                         # UNICODE + KEYUP\n        arr[lo].u.ki.dwExtraInfo = magic\n        arr[lo + 1].u.ki.dwExtraInfo = magic\n    return user32.SendInput(n, arr, ctypes.sizeof(INPUT))\n\n\ndef send_unicode_qtfix(text, magic=MAGIC):\n    """全角标点后注入 X 吸收 + Back 擦除 (Qt 应用吞字规避). 按 UTF-16 码元注入, 标点判断仅对 BMP."""\n    items = []\n    units = text.encode(\'utf-16-le\', \'surrogatepass\')\n    for i in range(len(units) // 2):\n        code = units[2 * i] | (units[2 * i + 1] << 8)\n        items.append((\'uk\', code))\n        items.append((\'ku\', code))\n        if 0x3000 <= code <= 0xFFFF and not (0x4E00 <= code <= 0x9FFF) and not (0x3400 <= code <= 0x4DBF) \\\n                and not (0xF900 <= code <= 0xFAFF):\n            items.append((\'uk\', ord(\'X\')))\n            items.append((\'ku\', ord(\'X\')))\n            items.append((\'dn\', 0x08))\n            items.append((\'up\', 0x08))\n    n = len(items)\n    arr = (INPUT * n)()\n    for i, (kind, val) in enumerate(items):\n        arr[i].type = 1\n        if kind == \'uk\':\n            arr[i].u.ki.wScan = val\n            arr[i].u.ki.dwFlags = 0x4\n            arr[i].u.ki.dwExtraInfo = magic\n        elif kind == \'ku\':\n            arr[i].u.ki.wScan = val\n            arr[i].u.ki.dwFlags = 0x4 | 0x2\n            arr[i].u.ki.dwExtraInfo = magic\n        elif kind == \'dn\':\n            arr[i].u.ki.wVk = val\n            arr[i].u.ki.dwExtraInfo = magic\n        else:\n            arr[i].u.ki.wVk = val\n            arr[i].u.ki.dwFlags = 0x2\n            arr[i].u.ki.dwExtraInfo = magic\n    return user32.SendInput(n, arr, ctypes.sizeof(INPUT))\n\n\ndef send_key_backspace(magic=MAGIC):\n    """向应用注入一个退格键 (VK 0x08 down+up, MAGIC 标记自家注入)."""\n    arr = (INPUT * 2)()\n    arr[0].type = 1\n    arr[0].u.ki.wVk = 0x08\n    arr[0].u.ki.dwExtraInfo = magic\n    arr[1].type = 1\n    arr[1].u.ki.wVk = 0x08\n    arr[1].u.ki.dwFlags = 0x2\n    arr[1].u.ki.dwExtraInfo = magic\n    return user32.SendInput(2, arr, ctypes.sizeof(INPUT))\n\n\n_paste_gen = [0]   # 剪贴板粘贴代际: 连续粘贴时旧恢复线程不覆盖新内容\n\n\ndef paste_text(text, magic=MAGIC):\n    """剪贴板粘贴 (提权窗口回退): 保存/恢复原剪贴板; 代际+读回校验防竞态覆盖."""\n    prev = clipboard_text()\n    if prev is not None and len(prev) == 0:\n        prev = None                                            # 空原文不恢复\n    _paste_gen[0] += 1\n    gen = _paste_gen[0]\n    clipboard_set(text)\n    import time\n    time.sleep(0.06)\n    # 注入 Ctrl+V\n    arr = (INPUT * 4)()\n    for i in range(4):\n        arr[i].type = 1\n        arr[i].u.ki.dwExtraInfo = magic\n    arr[0].u.ki.wVk = 0x11\n    arr[1].u.ki.wVk = 0x56\n    arr[2].u.ki.wVk = 0x56\n    arr[2].u.ki.dwFlags = 0x2\n    arr[3].u.ki.wVk = 0x11\n    arr[3].u.ki.dwFlags = 0x2\n    user32.SendInput(4, arr, ctypes.sizeof(INPUT))\n    time.sleep(0.15)\n    if prev:\n        import threading\n        def restore():\n            time.sleep(0.3)\n            if _paste_gen[0] == gen and clipboard_text() == text:   # 无新粘贴且剪贴板仍是我们设的值才恢复\n                clipboard_set(prev)\n        threading.Thread(target=restore, daemon=True).start()\n\n\n# ---------- 剪贴板 (ctypes 原生, 零子进程/零编码问题) ----------\nuser32.OpenClipboard.restype = w.BOOL\nuser32.OpenClipboard.argtypes = [ctypes.c_void_p]\nuser32.GetClipboardData.restype = ctypes.c_void_p\nuser32.GetClipboardData.argtypes = [w.UINT]\nuser32.SetClipboardData.restype = ctypes.c_void_p\nuser32.SetClipboardData.argtypes = [w.UINT, ctypes.c_void_p]\nuser32.EmptyClipboard.restype = w.BOOL\nkernel32.GlobalAlloc.restype = ctypes.c_void_p\nkernel32.GlobalAlloc.argtypes = [w.UINT, ctypes.c_size_t]\nkernel32.GlobalLock.restype = ctypes.c_void_p\nkernel32.GlobalLock.argtypes = [ctypes.c_void_p]\nkernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]\n\n\ndef clipboard_text():\n    """读剪贴板文本 (ctypes 原生, 零子进程/零编码问题); 非文本/失败返回 None."""\n    if not user32.OpenClipboard(0):\n        return None\n    try:\n        h = user32.GetClipboardData(13)            # CF_UNICODETEXT\n        if not h:\n            return None\n        p = kernel32.GlobalLock(h)\n        if not p:\n            return None\n        try:\n            return ctypes.wstring_at(p)\n        finally:\n            kernel32.GlobalUnlock(h)\n    finally:\n        user32.CloseClipboard()\n\n\ndef clipboard_set(text):\n    """写剪贴板文本 (ctypes 原生); 失败静默."""\n    if text is None:\n        text = \'\'\n    try:\n        user32.OpenClipboard(0)\n    except Exception:\n        return\n    try:\n        user32.EmptyClipboard()\n        data = (str(text) + \'\\0\').encode(\'utf-16-le\')\n        h = kernel32.GlobalAlloc(0x0002, len(data))   # GMEM_MOVEABLE\n        if not h:\n            return\n        p = kernel32.GlobalLock(h)\n        if p:\n            ctypes.memmove(p, data, len(data))\n            kernel32.GlobalUnlock(h)\n            user32.SetClipboardData(13, h)            # CF_UNICODETEXT\n    finally:\n        user32.CloseClipboard()\n\n\n# ---------- 光标跟随 ----------\nclass RECT(ctypes.Structure):\n    _fields_ = [(\'left\', ctypes.c_long), (\'top\', ctypes.c_long), (\'right\', ctypes.c_long), (\'bottom\', ctypes.c_long)]\n\n\nclass POINT(ctypes.Structure):\n    _fields_ = [(\'x\', ctypes.c_long), (\'y\', ctypes.c_long)]\n\n\nclass GUITHREADINFO(ctypes.Structure):\n    _fields_ = [(\'cbSize\', w.DWORD), (\'flags\', w.DWORD), (\'hwndActive\', w.HWND), (\'hwndFocus\', w.HWND),\n                (\'hwndCapture\', w.HWND), (\'hwndMenuOwner\', w.HWND), (\'hwndMoveSize\', w.HWND),\n                (\'hwndCaret\', w.HWND), (\'rcCaret\', RECT)]\n\n\n_last_caret = [None]\n_uia = [None]\n\n\ndef get_caret_uia():\n    """UI Automation 光标 (现代应用 Edge/Explorer/Office, GetGUIThreadInfo 探测不到时)."""\n    try:\n        if _uia[0] is None:\n            import uiautomation as auto\n            _uia[0] = auto\n        auto = _uia[0]\n        el = auto.GetFocusedControl()\n        if not el:\n            return None\n        # 精确光标: ITextPattern.GetSelection(); caret 是细矩形(高 4~200, 宽<=200),\n        # 太宽 = 整行/段落(某些 Chromium 字段) -> 不信任, 回退到控件边界\n        try:\n            tp = el.GetPattern(auto.PatternId.TextPattern)\n            if tp:\n                sel = tp.GetSelection()\n                if sel and len(sel) > 0:\n                    rects = sel[0].GetBoundingRectangles()\n                    if rects:\n                        r = rects[0]\n                        cw = r.right - r.left\n                        ch = r.bottom - r.top\n                        if 0 < cw <= 200 and 4 <= ch <= 200:\n                            return (int(r.left), int(r.bottom))\n        except Exception:\n            pass\n        # 回退: 聚焦控件边界 (只算小控件, 避免全屏/整窗)\n        r = el.BoundingRectangle\n        cw = r.right - r.left\n        ch = r.bottom - r.top\n        if 0 < cw < 2000 and 0 < ch < 400:\n            return (int(r.left), int(r.bottom))\n    except Exception:\n        pass\n    return None\n\n\ndef get_caret_pos():\n    """光标屏幕坐标. GetGUIThreadInfo -> UIA -> 上次有效位 -> 前台窗口客户区."""\n    try:\n        fg = user32.GetForegroundWindow()\n        tid = user32.GetWindowThreadProcessId(fg, None)\n        g = GUITHREADINFO()\n        g.cbSize = ctypes.sizeof(GUITHREADINFO)\n        if user32.GetGUIThreadInfo(tid, ctypes.byref(g)) and g.hwndCaret:\n            pt = POINT(g.rcCaret.left, g.rcCaret.bottom)\n            user32.ClientToScreen(g.hwndCaret, ctypes.byref(pt))\n            _last_caret[0] = (pt.x, pt.y)\n            return _last_caret[0]\n    except Exception:\n        pass\n    p = get_caret_uia()\n    if p:\n        _last_caret[0] = p\n        return p\n    if _last_caret[0]:\n        return _last_caret[0]\n    return _foreground_client_origin()\n\n\ndef _foreground_client_origin():\n    """前台窗口客户区左上角的屏幕坐标 (光标探测失败的回退)."""\n    try:\n        fg = user32.GetForegroundWindow()\n        if not fg:\n            return None\n        pt = POINT(0, 0)\n        user32.ClientToScreen(fg, ctypes.byref(pt))\n        return pt.x + 12, pt.y + 40\n    except Exception:\n        return None\n\n\ndef screen_workarea():\n    r = RECT()\n    user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(r), 0)\n    return r\n\n\ndef set_topmost(hwnd):\n    """把窗口提到 topmost z-order 最顶(Win11 开始菜单等 Shell 层会比普通 topmost 更高, 用它压回)."""\n    try:\n        user32.SetWindowPos.restype = w.BOOL\n        user32.SetWindowPos.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int, ctypes.c_int,\n                                        ctypes.c_int, ctypes.c_int, w.UINT]\n        flags = 0x0001 | 0x0002 | 0x0010                       # SWP_NOSIZE | SWP_NOMOVE | SWP_NOACTIVATE\n        user32.SetWindowPos(ctypes.c_void_p(hwnd), ctypes.c_void_p(-1), 0, 0, 0, 0, flags)\n    except Exception:\n        pass\n\n\nclass MONITORINFO(ctypes.Structure):\n    _fields_ = [(\'cbSize\', w.DWORD), (\'rcMonitor\', RECT), (\'rcWork\', RECT), (\'dwFlags\', w.DWORD)]\n\n\ndef workarea_at(x, y):\n    """返回 (x,y) 所在显示器的工作区 (多屏正确)."""\n    try:\n        pt = POINT(int(x), int(y))\n        hmon = user32.MonitorFromPoint(pt, 2)                # MONITOR_DEFAULTTONEAREST\n        mi = MONITORINFO()\n        mi.cbSize = ctypes.sizeof(MONITORINFO)\n        if user32.GetMonitorInfoW(hmon, ctypes.byref(mi)):\n            return mi.rcWork\n    except Exception:\n        pass\n    return screen_workarea()\n\n\nclass CURSORINFO(ctypes.Structure):\n    _fields_ = [(\'cbSize\', w.DWORD), (\'flags\', w.DWORD), (\'hCursor\', ctypes.c_void_p), (\'ptScreenPos\', POINT)]\n\n\ndef cursor_pos():\n    p = POINT()\n    user32.GetCursorPos(ctypes.byref(p))\n    return p.x, p.y\n\n\ndef get_pixel(x, y):\n    hdc = user32.GetDC(0)\n    try:\n        px = gdi32.GetPixel(hdc, x, y)\n    finally:\n        user32.ReleaseDC(0, hdc)\n    if px == 0xFFFFFFFF:      # CLR_INVALID: 取色失败(越屏/无DC) -> None, 避免误判为白色\n        return None\n    return px & 0xFF, (px >> 8) & 0xFF, (px >> 16) & 0xFF\n\n\ndef foreground_process_name():\n    try:\n        fg = user32.GetForegroundWindow()\n        pid = w.DWORD()\n        user32.GetWindowThreadProcessId(fg, ctypes.byref(pid))\n        h = kernel32.OpenProcess(0x1000, False, pid.value)\n        if not h:\n            return \'\'\n        try:\n            buf = ctypes.create_unicode_buffer(512)\n            size = w.DWORD(512)\n            if kernel32.QueryFullProcessImageNameW(h, 0, buf, ctypes.byref(size)):\n                return os.path.splitext(os.path.basename(buf.value))[0].lower()\n        finally:\n            kernel32.CloseHandle(h)\n    except Exception:\n        pass\n    return \'\'\n\n\ndef self_elevated():\n    try:\n        return bool(ctypes.windll.shell32.IsUserAnAdmin())\n    except Exception:\n        return False\n\n\ndef foreground_elevated():\n    try:\n        fg = user32.GetForegroundWindow()\n        pid = w.DWORD()\n        user32.GetWindowThreadProcessId(fg, ctypes.byref(pid))\n        h = kernel32.OpenProcess(0x1000, False, pid.value)\n        if not h:\n            return False\n        try:\n            tok = w.HANDLE()\n            if not ctypes.windll.advapi32.OpenProcessToken(h, 0x8, ctypes.byref(tok)):\n                return False\n            try:\n                elev = w.DWORD()\n                size = w.DWORD()\n                ok = ctypes.windll.advapi32.GetTokenInformation(tok, 20, ctypes.byref(elev), 4, ctypes.byref(size))\n                return bool(ok and elev.value != 0)\n            finally:\n                kernel32.CloseHandle(tok)\n        finally:\n            kernel32.CloseHandle(h)\n    except Exception:\n        return False\n', 'hook': '# -*- coding: utf-8 -*-\n"""hook.py — WH_KEYBOARD_LL via ctypes. 钩子线程只做吞键判定 + 入队 (关键路径零 Python GIL 风险).\n事件: Vk int (真实键) 或合成码 (0xF8 Shift轻拍切换 / 0xF9 Ctrl+`模式 / 0xFA Ctrl+Shift+F繁简 / 0xFB Ctrl+Alt+C造词).\n"""\nimport ctypes\nimport ctypes.wintypes as w\nimport queue\nimport time\nimport threading\n\nuser32 = ctypes.windll.user32\nkernel32 = ctypes.windll.kernel32\n\nWH_KEYBOARD_LL = 13\nWM_KEYDOWN = 0x0100\nWM_SYSKEYDOWN = 0x0104\nWM_KEYUP = 0x0101\nWM_SYSKEYUP = 0x0105\nHC_ACTION = 0\nLLKHF_INJECTED = 0x10\n\nVK_TOGGLE = 0x77        # F8 (硬开关)\nVK_TAP = 0xF8           # 合成: Shift 轻拍\nVK_MODE = 0xF9          # 合成: Ctrl+`\nVK_TRAD = 0xFA          # 合成: Ctrl+Shift+F\nVK_MAKEWORD = 0xFB      # 合成: Ctrl+Alt+C\nVK_QUIT = 0xFC          # 合成: Ctrl+Alt+Q 退出\n\nACTIVE = [False]        # 输入法是否启用 (主线程写入, 钩子线程判定)\nCOMPOSING = [False]     # 是否有拼音缓冲/联想 (主线程写入; 空缓冲时空格/退格/回车透传)\n\nEVENTS = queue.Queue()\n\n\nclass KBDLLHOOKSTRUCT(ctypes.Structure):\n    _fields_ = [(\'vkCode\', w.DWORD), (\'scanCode\', w.DWORD), (\'flags\', w.DWORD),\n                (\'time\', w.DWORD), (\'dwExtraInfo\', ctypes.c_ssize_t)]\n\n\nHOOKPROC = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, ctypes.c_int, ctypes.c_size_t, ctypes.c_ssize_t)\n\n# 正确原型 (64 位指针参数必须声明, 否则默认 32 位溢出)\nuser32.SetWindowsHookExW.restype = ctypes.c_void_p\nuser32.SetWindowsHookExW.argtypes = [ctypes.c_int, HOOKPROC, ctypes.c_void_p, w.DWORD]\nuser32.CallNextHookEx.restype = ctypes.c_ssize_t\nuser32.CallNextHookEx.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_size_t, ctypes.c_ssize_t]\nuser32.GetMessageW.restype = ctypes.c_int\nuser32.GetMessageW.argtypes = [ctypes.POINTER(w.MSG), ctypes.c_void_p, w.UINT, w.UINT]\nuser32.GetKeyState.restype = ctypes.c_short\nuser32.GetKeyState.argtypes = [ctypes.c_int]\n\n\n_CTRL_KEYS = {0x20, 0x08, 0x1B, 0x0D, 0xBD, 0xBB, 0xDB, 0xDD, 0xBA}   # 空格/退格/esc/回车/-/=/[/]/; : 仅缓冲有效时吞\n\n\ndef _key_state(vk):\n    return (user32.GetKeyState(vk) & 0x8000) != 0\n\n\n_hook = [None]\n\n\ndef _proc(nCode, wParam, lParam):\n    try:\n        if nCode >= 0:\n            kbd = ctypes.cast(lParam, ctypes.POINTER(KBDLLHOOKSTRUCT)).contents\n            # 所有注入键(第三方宏/AHK/远程桌面)一律放行不吞, 与 C# 版对齐\n            if (kbd.flags & LLKHF_INJECTED):\n                return user32.CallNextHookEx(None, nCode, wParam, lParam)\n            m = int(wParam)\n            vk = int(kbd.vkCode)\n            if m == WM_KEYDOWN or m == WM_SYSKEYDOWN:\n                if vk == VK_TOGGLE:                            # F8 硬开关: 带修饰键则透传(不劫持 Ctrl+F8/Shift+F8 等)\n                    if (_key_state(0x11) or _key_state(0x12) or _key_state(0x10)\n                            or _key_state(0x5B) or _key_state(0x5C)):\n                        return user32.CallNextHookEx(None, nCode, wParam, lParam)\n                    EVENTS.put(VK_TOGGLE)\n                    return 1\n                if _key_state(0x11) and _key_state(0x12) and vk == 0x51:   # Ctrl+Alt+Q 退出\n                    EVENTS.put(VK_QUIT)\n                    return 1\n                ctrl = _key_state(0x11)\n                shift = _key_state(0x10)\n                alt = _key_state(0x12)\n                if vk in (0xA0, 0xA1):                         # Shift down\n                    # 带 Ctrl/Alt/Win 时不武装轻拍(避免 Ctrl+Shift/Alt+Shift 误触发开关)\n                    if ctrl or alt or _key_state(0x5B) or _key_state(0x5C):\n                        _tap_time[0] = None\n                        _tap_dirty[0] = True\n                    else:\n                        _tap_time[0] = time.time()\n                        _tap_dirty[0] = False\n                else:\n                    if _tap_time[0] is not None:\n                        _tap_dirty[0] = True                   # 有其它键介入, 不算轻拍\n                    if ACTIVE[0]:\n                        if ctrl and vk == 0xC0:                # Ctrl+` 模式 (激活态)\n                            EVENTS.put(VK_MODE)\n                            return 1\n                        if ctrl and shift and vk == 0x46:      # Ctrl+Shift+F 繁简 (激活态)\n                            EVENTS.put(VK_TRAD)\n                            return 1\n                        if ctrl and alt and vk == 0x43:        # Ctrl+Alt+C 造词 (激活态)\n                            EVENTS.put(VK_MAKEWORD)\n                            return 1\n                        winkey = _key_state(0x5B) or _key_state(0x5C)\n                        if ctrl or alt or winkey:              # 带 Ctrl/Alt/Win 的快捷键: 透传\n                            return user32.CallNextHookEx(None, nCode, wParam, lParam)\n                        if shift:                              # Shift 修正键: 透传\n                            return user32.CallNextHookEx(None, nCode, wParam, lParam)\n                        if 0x41 <= vk <= 0x5A:                 # 裸字母: 吞 (开始拼音)\n                            EVENTS.put(vk)\n                            return 1\n                        if 0x30 <= vk <= 0x39 and COMPOSING[0]:   # 数字: 仅组字/联想时吞(候选选择/v模式), 裸数字透传(C# 对齐)\n                            EVENTS.put(vk)\n                            return 1\n                        if vk in _CTRL_KEYS and COMPOSING[0]:  # 空格/退格/回车等: 仅缓冲有效时吞\n                            EVENTS.put(vk)\n                            return 1\n                        # 其余键透传 (无缓冲时空格/退格/回车交给应用)\n            elif m == WM_KEYUP or m == WM_SYSKEYUP:\n                if vk in (0xA0, 0xA1):\n                    if _tap_time[0] is not None and not _tap_dirty[0] \\\n                            and time.time() - _tap_time[0] < 0.4:\n                        EVENTS.put(VK_TAP)                     # 孤立快速 Shift 轻拍: 切换 (激活/关闭)\n                    _tap_time[0] = None\n    except Exception:\n        return user32.CallNextHookEx(None, nCode, wParam, lParam)\n    return user32.CallNextHookEx(None, nCode, wParam, lParam)\n\n\n_tap_time = [None]\n_tap_dirty = [True]\n\n\ndef _pump():\n    msg = w.MSG()\n    while user32.GetMessageW(ctypes.byref(msg), None, 0, 0) > 0:\n        user32.TranslateMessage(ctypes.byref(msg))\n        user32.DispatchMessageW(ctypes.byref(msg))\n\n\n_started = [False]\n\n\ndef start():\n    if _started[0]:\n        return\n    _started[0] = True\n    _hook[0] = HOOKPROC(_proc)\n    th = threading.Thread(target=lambda: (user32.SetWindowsHookExW(WH_KEYBOARD_LL, _hook[0], None, 0), _pump()), daemon=True)\n    th.start()\n\n\ndef set_active(on):\n    ACTIVE[0] = bool(on)\n\n\ndrain = EVENTS.get\n', 'bar': '# -*- coding: utf-8 -*-\n"""bar.py — tkinter 无边框置顶候选条 (真透明圆角 transparentcolor, 跟随光标, 分页指示, 双主题, 无边框)."""\nimport tkinter as tk\nimport tkinter.font as tkfont\n\nimport win\n\nTRANSPARENT = \'#010203\'   # 透明关键色 (圆角四角透明)\n\n# 双主题: dark = C# Morandi 深灰褐; light = 白底\nTHEMES = {\n    \'dark\': dict(bg=\'#3B3836\', text=\'#FFFFFF\', sub=\'#B0ACA8\', accent=\'#007AFF\', alpha=0.88),\n    \'light\': dict(bg=\'#FFFFFF\', text=\'#1D1D1F\', sub=\'#6E7485\', accent=\'#007AFF\', alpha=0.95),\n}\n\n\nclass CandBar:\n    def __init__(self, root):\n        self.root = root\n        self.theme = \'dark\'\n        self.top = tk.Toplevel(root)\n        self.top.overrideredirect(True)\n        self.top.attributes(\'-topmost\', True)\n        self.top.attributes(\'-toolwindow\', True)\n        self.top.configure(bg=TRANSPARENT)\n        try:\n            self.top.attributes(\'-transparentcolor\', TRANSPARENT)   # 真透明圆角 (四角透明)\n        except Exception:\n            pass\n        self.canvas = tk.Canvas(self.top, bg=TRANSPARENT, highlightthickness=0, bd=0)\n        self.canvas.pack(fill=\'both\', expand=True)\n        self.canvas.bind(\'<ButtonPress-1>\', self._drag_start)\n        self.canvas.bind(\'<B1-Motion>\', self._drag_move)\n        self._drag = {\'x\': 0, \'y\': 0}\n        self._pad = 10\n        self._fc = tkfont.Font(family=\'Microsoft YaHei UI\', size=9)\n        self._fd = tkfont.Font(family=\'Microsoft YaHei UI\', size=11)\n\n    def set_theme(self, name):\n        if name in THEMES:\n            self.theme = name\n            self.top.attributes(\'-alpha\', THEMES[name][\'alpha\'])\n\n    def _round_rect(self, c, x1, y1, x2, y2, r, **kw):\n        r = min(r, (x2 - x1) // 2, (y2 - y1) // 2)\n        c.create_polygon([(x1 + r, y1), (x2 - r, y1), (x2, y1), (x2, y1 + r), (x2, y2 - r), (x2, y2),\n                          (x2 - r, y2), (x1 + r, y2), (x1, y2), (x1, y2 - r), (x1, y1 + r), (x1, y1)],\n                         smooth=True, **kw)\n\n    def show(self, header, code, cands, sel, page=0, total=1, follow=True, fixed=None):\n        t = THEMES[self.theme]\n        c = self.canvas\n        c.delete(\'all\')\n        # 候选显示截断: 超长词(整句/长词)截断 + 省略号, 避免候选条无限宽\n        wa = win.screen_workarea()\n        # 候选条最大宽度: 不铺满屏, 封顶 min(屏幕宽-24, 880px); ≥240\n        max_w = max(240, min((wa.right - wa.left) - 24, 880))\n        def clip(s, n):\n            return s if len(s) <= n else s[:n] + \'…\'\n        line1 = self._pad + self._fc.measure(header) + self._fc.measure(code)\n        page_ind = \'◀ %d/%d ▶\' % (page + 1, total) if total > 1 else \'\'\n        ind_w = self._fc.measure(page_ind) if page_ind else 0\n        # 动态收紧候选截断: 候选总宽超 max_w 时, 逐步缩短每个候选(24→8), 直到候选条不铺满屏,\n        # 且每个候选仍可见(都剪短, 数字键/翻页可选); 到最小仍超则窗口封顶 max_w 自动裁\n        cands = list(cands or [])\n        clipped = cands\n        line2 = self._pad\n        for n in range(24, 7, -2):\n            clipped = [clip(x, n) for x in cands]\n            line2 = self._pad\n            for i2, cnd in enumerate(clipped):\n                line2 += self._fd.measure(\'%d.%s\' % (i2 + 1, cnd)) + 16\n            if line2 <= max_w or n <= 8:\n                break\n        cands = clipped\n        w = max(line1 + ind_w + 18, line2 + self._pad, 120)\n        w = min(w, max_w)                              # 钳制到候选条最大宽度, 不再无限长\n        h = 54\n        # 圆角底 (fill=主题底; 四角透明由 transparentcolor 提供)\n        self._round_rect(c, 0, 0, w - 1, h - 1, 10, fill=t[\'bg\'])\n        # header + code (行1)\n        y = 6\n        x = self._pad\n        c.create_text(x, y, anchor=\'nw\', text=header, fill=t[\'accent\'], font=self._fc)\n        x += self._fc.measure(header)\n        c.create_text(x, y, anchor=\'nw\', text=code, fill=t[\'sub\'], font=self._fc)\n        if page_ind:\n            c.create_text(w - self._pad, y, anchor=\'ne\', text=page_ind, fill=t[\'sub\'], font=self._fc)\n        # candidates (行2)\n        y = 26\n        x = self._pad\n        for i, cand in enumerate(cands):\n            text = \'%d.%s\' % (i + 1, cand)\n            tw = self._fd.measure(text)\n            if i == sel:\n                self._round_rect(c, x - 4, y, x + tw + 8, y + 26, 6, fill=t[\'accent\'])\n                c.create_text(x + 2, y + 13, anchor=\'w\', text=text, fill=\'#FFFFFF\', font=self._fd)\n            else:\n                c.create_text(x + 2, y + 13, anchor=\'w\', text=text, fill=t[\'text\'], font=self._fd)\n            x += tw + 16\n        # 定位: 固定位置(fixed) > 跟随光标(多屏钳制) > 开始菜单/搜索 Shell 固定右下角 > 拖动保持\n        _shell = win.foreground_process_name() in (\'startmenuexperiencehost\', \'searchhost\', \'shellexperiencehost\')\n        if isinstance(fixed, (tuple, list)):\n            self.top.geometry(\'%dx%d+%d+%d\' % (w, h, fixed[0], fixed[1]))\n        elif fixed == \'bottom-right\':\n            ra = win.screen_workarea()\n            self.top.geometry(\'%dx%d+%d+%d\' % (w, h, ra.right - w - 16, ra.bottom - h - 8))\n        elif fixed == \'bottom-center\':\n            ra = win.screen_workarea()\n            self.top.geometry(\'%dx%d+%d+%d\' % (w, h, ra.left + (ra.right - ra.left - w) // 2, ra.bottom - h - 8))\n        elif follow and not _shell:\n            pos = win.get_caret_pos()\n            if pos:\n                cx, cy = pos\n                ra = win.workarea_at(cx, cy)\n                x = cx\n                y = cy + 6\n                if x + w > ra.right:\n                    x = ra.right - w\n                if x < ra.left:\n                    x = ra.left\n                if y + h > ra.bottom:\n                    y = cy - h - 6\n                if y < ra.top:\n                    y = ra.top\n                self.top.geometry(\'%dx%d+%d+%d\' % (w, h, x, y))\n            else:\n                ra = win.screen_workarea()\n                self.top.geometry(\'%dx%d+%d+%d\' % (w, h, ra.left + (ra.right - ra.left - w) // 2, ra.bottom - h - 40))\n        elif _shell:\n            # 开始菜单/搜索类 UI: 固定屏幕右下角并贴着任务栏上方(避开浮窗, 不遮挡中央)\n            ra = win.screen_workarea()\n            self.top.geometry(\'%dx%d+%d+%d\' % (w, h, ra.right - w - 16, ra.bottom - h - 8))\n        else:\n            # 固定模式(用户可拖动): 保持当前位置, 但候选变宽/高时 clamp 到工作区, 避免超屏看不到\n            ra = win.screen_workarea()\n            cx, cy = self.top.winfo_x(), self.top.winfo_y()\n            if not cx and not cy:\n                cx, cy = ra.left + (ra.right - ra.left - w) // 2, ra.bottom - h - 40\n            if cx + w > ra.right:\n                cx = ra.right - w\n            if cx < ra.left:\n                cx = ra.left\n            if cy + h > ra.bottom:\n                cy = ra.bottom - h\n            if cy < ra.top:\n                cy = ra.top\n            self.top.geometry(\'%dx%d+%d+%d\' % (w, h, cx, cy))\n        self.top.deiconify()\n        win.set_topmost(self.top.winfo_id())   # 强制提到 topmost z-order 最顶(Win11 开始菜单不压住候选框)\n\n    def _drag_start(self, e):\n        self._drag[\'x\'] = e.x_root - self.top.winfo_x()\n        self._drag[\'y\'] = e.y_root - self.top.winfo_y()\n\n    def _drag_move(self, e):\n        self.top.geometry(\'+%d+%d\' % (e.x_root - self._drag[\'x\'], e.y_root - self._drag[\'y\']))\n\n    def hide(self):\n        self.top.withdraw()\n', 'wspy': '# -*- coding: utf-8 -*-\n"""wspy.py — 最小同步 WebSocket 客户端 (标准库 socket+ssl, RFC 6455). 用于 relay 文本帧 / MQTT-over-WS 二进制帧."""\nimport base64\nimport os\nimport socket\nimport ssl\nimport struct\nfrom urllib.parse import urlparse\n\nOP_CONT = 0x0\nOP_TEXT = 0x1\nOP_BIN = 0x2\nOP_CLOSE = 0x8\nOP_PING = 0x9\nOP_PONG = 0xA\n\n\nclass WS:\n    def __init__(self):\n        self.sock = None\n        self.subprotocol = None\n\n    def connect(self, url, subprotocol=None, timeout=10):\n        u = urlparse(url)\n        host = u.hostname\n        port = u.port or (443 if u.scheme == \'wss\' else 80)\n        path = u.path or \'/\'\n        if u.query:\n            path += \'?\' + u.query\n        if u.scheme == \'wss\':\n            ctx = ssl.create_default_context()\n            self.sock = ctx.wrap_socket(socket.create_connection((host, port), timeout=timeout), server_hostname=host)\n        else:\n            self.sock = socket.create_connection((host, port), timeout=timeout)\n        self.sock.settimeout(30)\n        key = base64.b64encode(os.urandom(16)).decode()\n        req = (\'GET %s HTTP/1.1\\r\\nHost: %s\\r\\nUpgrade: websocket\\r\\nConnection: Upgrade\\r\\n\'\n               \'Sec-WebSocket-Key: %s\\r\\nSec-WebSocket-Version: 13\\r\\n\' % (path, host, key))\n        if subprotocol:\n            req += \'Sec-WebSocket-Protocol: %s\\r\\n\' % subprotocol\n        req += \'\\r\\n\'\n        self.sock.sendall(req.encode())\n        head = self._read_headers()\n        status = head.split(\'\\r\\n\', 1)[0]\n        if \' 101 \' not in status:\n            raise RuntimeError(\'handshake failed: \' + status)\n        self.subprotocol = self._header(head, \'Sec-WebSocket-Protocol\') or subprotocol\n\n    def _read_headers(self):\n        buf = b\'\'\n        while b\'\\r\\n\\r\\n\' not in buf:\n            chunk = self.sock.recv(4096)\n            if not chunk:\n                raise RuntimeError(\'connection closed during handshake\')\n            buf += chunk\n        return buf.decode(\'utf-8\', errors=\'replace\')\n\n    @staticmethod\n    def _header(head, name):\n        for line in head.split(\'\\r\\n\'):\n            if line.lower().startswith(name.lower() + \':\'):\n                return line.split(\':\', 1)[1].strip()\n        return None\n\n    # ---------- frames ----------\n    def _send_frame(self, payload, opcode):\n        mask = os.urandom(4)\n        head = bytearray()\n        head.append(0x80 | opcode)\n        n = len(payload)\n        if n < 126:\n            head.append(0x80 | n)\n        elif n < 0x10000:\n            head.append(0x80 | 126)\n            head += struct.pack(\'>H\', n)\n        else:\n            head.append(0x80 | 127)\n            head += struct.pack(\'>Q\', n)\n        head += mask\n        masked = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))\n        self.sock.sendall(bytes(head) + masked)\n\n    def send_text(self, s):\n        self._send_frame(s.encode(\'utf-8\'), OP_TEXT)\n\n    def send_bin(self, b):\n        self._send_frame(b, OP_BIN)\n\n    def _recv_frame(self):\n        h = self._readexact(2)\n        opcode = h[0] & 0x0F\n        masked = (h[1] & 0x80) != 0\n        n = h[1] & 0x7F\n        if n == 126:\n            n = struct.unpack(\'>H\', self._readexact(2))[0]\n        elif n == 127:\n            n = struct.unpack(\'>Q\', self._readexact(8))[0]\n        mask = self._readexact(4) if masked else None\n        payload = self._readexact(n)\n        if mask:\n            payload = bytes(b ^ mask[i % 4] for i, b in enumerate(payload))\n        return opcode, payload\n\n    def _readexact(self, n):\n        buf = b\'\'\n        while len(buf) < n:\n            chunk = self.sock.recv(n - len(buf))\n            if not chunk:\n                raise RuntimeError(\'connection closed\')\n            buf += chunk\n        return buf\n\n    def _read_message(self):\n        """拼一个完整消息 (聚合分片), 返回 (opcode, payload)."""\n        opcode, payload = self._recv_frame()\n        data = payload\n        fin_opcode = opcode\n        while opcode == OP_CONT or (opcode in (OP_PING, OP_PONG)):\n            if opcode == OP_PING:\n                self._send_frame(payload, OP_PONG)\n            elif opcode == OP_PONG:\n                pass\n            else:\n                po, pw = self._recv_frame()\n                data += pw\n                opcode = po\n                break\n            opcode, payload = self._recv_frame()\n            if opcode != OP_CONT:\n                break\n        return fin_opcode, data\n\n    def recv_message(self):\n        return self._read_message()\n\n    def close(self):\n        try:\n            self._send_frame(b\'\', OP_CLOSE)\n        except Exception:\n            pass\n        try:\n            self.sock.close()\n        except Exception:\n            pass\n', 'engine': '# -*- coding: utf-8 -*-\n"""wgime-py engine: dict loading, candidate assembly, freq learning.\n\n逐行对齐 C# WordBoard 语义 (wgime.bat):\n- 码表格式: "code word1 word2 ..." (小写 code; 文件源不拆 packed chars)\n- 候选顺序 (ShowCharatar): exact dict -> prefix 单字 -> 简拼 -> 模糊音 -> 词频排序(稳定) -> lastpick 置顶\n- 模式: 0=混合(五笔先) 1=拼音 2=五笔 3=词典(英汉/汉英)\n- 词频: FreqM[mode] 分桶 + Freq 合并视图; userdict_{mix,py,wb}.txt / lastpick_*.txt 与 C# 版同格式\n"""\nimport bisect\nimport math\nimport os\nimport re\nimport sys\nimport threading\nimport time\nfrom collections import deque\n\nRE_CAP = 500      # 近期热度滑动窗口: 最近上屏的 (mode, word) 数, 超出溢出最旧 -> 自动过期\nCAND_CAP = 60\nPAGE_SIZE = 9\nMODE_SUFFIX = (\'mix\', \'py\', \'wb\')\nFUZZY_PAIRS = ((\'zh\', \'z\'), (\'ch\', \'c\'), (\'sh\', \'s\'), (\'ang\', \'an\'), (\'eng\', \'en\'), (\'ing\', \'in\'), (\'n\', \'l\'))\n\n# ---------- vf 符号面板数据 (抽自 C# SymCats) ----------\nSYM_CAT_NAMES = [\'单位符号\', \'标点符号\', \'图形符号\', \'数学符号\', \'表情emoji\']\nSYM_CATS = [\n    \'℃ ℉ ° ′ ″ ‰ ㎎ ㎏ ㎜ ㎝ ㎞ ㎡ ㎥ ㏄ №\',\n    \'… — ～ · § ※ 《 》 〈 〉 「 」 『 』 〔 〕 〖 〗 【 】 ￥\',\n    \'★ ☆ ● ○ ◆ ◇ ■ □ ▲ △ ► ◄ ♥ ♣ ♠ ♦ ♪ ♫ ♀ ♂ ☀ ☁ ☂ ☃ ☺ ☹ ✓ ✔ ✕ ✖ ☑ ➜ → ← ↑ ↓ ↔\',\n    \'± × ÷ ≤ ≥ ≠ ≈ ∞ √ ∑ ∫ ∮ ∂ ∇ ∈ ∉ ⊂ ⊃ ⊆ ∪ ∩ ∅ ∴ ∵ α β γ δ θ λ μ π σ φ ω\',\n    \'😀 😁 😂 🤣 😊 😍 😘 😎 🤔 😴 😢 😭 😡 👍 👎 👌 ✌ 🤝 🙏 💪 👀 🎉 ❤️ 💔 💯 🔥 ⭐ 🚀 🌈 🍀 ⚡ 🌙 ☕\',\n]\n\n# ---------- 双拼规则 (抽自 C# SpRules; rime preedit_format, $1 -> \\g<1>) ----------\ndef _R(rules):\n    return [(re.compile(p), r.replace(\'$1\', \'\\\\g<1>\').replace(\'$2\', \'\\\\g<2>\')) for p, r in rules]\n\nSP_RULES = [\n    _R([  # 1: 小鹤 (flypy)\n        (r\'([bpmfdtnljqx])n\', \'$1iao\'), (r\'(\\w)g\', \'$1eng\'), (r\'(\\w)q\', \'$1iu\'),\n        (r\'(\\w)w\', \'$1ei\'), (r\'([dtnlgkhjqxyvuirzcs])r\', \'$1uan\'), (r\'(\\w)t\', \'$1ve\'),\n        (r\'(\\w)y\', \'$1un\'), (r\'([dtnlgkhvuirzcs])o\', \'$1uo\'), (r\'(\\w)p\', \'$1ie\'),\n        (r\'([jqx])s\', \'$1iong\'), (r\'(\\w)s\', \'$1ong\'), (r\'(\\w)d\', \'$1ai\'),\n        (r\'(\\w)f\', \'$1en\'), (r\'(\\w)h\', \'$1ang\'), (r\'(\\w)j\', \'$1an\'),\n        (r\'([gkhvuirzcs])k\', \'$1uai\'), (r\'(\\w)k\', \'$1ing\'), (r\'([jqxnl])l\', \'$1iang\'),\n        (r\'(\\w)l\', \'$1uang\'), (r\'(\\w)z\', \'$1ou\'), (r\'([gkhvuirzcs])x\', \'$1ua\'),\n        (r\'(\\w)x\', \'$1ia\'), (r\'(\\w)c\', \'$1ao\'), (r\'([dtgkhvuirzcs])v\', \'$1ui\'),\n        (r\'(\\w)b\', \'$1in\'), (r\'(\\w)m\', \'$1ian\'), (r\'([aoe])\\1(\\w)\', \'$1$2\'),\n        (r\'^v\', \'zh\'), (r\'^i\', \'ch\'), (r\'^u\', \'sh\'),\n        (r\'([jqxy])v\', \'$1u\'), (r\'([nl])v\', \'$1ü\'),\n    ]),\n    _R([  # 2: 自然码\n        (r\'([bpmnljqxy])n\', \'$1in\'), (r\'(\\w)g\', \'$1eng\'), (r\'(\\w)q\', \'$1iu\'),\n        (r\'([gkhvuirzcs])w\', \'$1ua\'), (r\'(\\w)w\', \'$1ia\'), (r\'([dtnlgkhjqxyvuirzcs])r\', \'$1uan\'),\n        (r\'(\\w)t\', \'$1ve\'), (r\'([gkhvuirzcs])y\', \'$1uai\'), (r\'(\\w)y\', \'$1ing\'),\n        (r\'([dtnlgkhvuirzcs])o\', \'$1uo\'), (r\'(\\w)p\', \'$1un\'), (r\'([jqx])s\', \'$1iong\'),\n        (r\'(\\w)s\', \'$1ong\'), (r\'([jqxnl])d\', \'$1iang\'), (r\'(\\w)d\', \'$1uang\'),\n        (r\'(\\w)f\', \'$1en\'), (r\'(\\w)h\', \'$1ang\'), (r\'(\\w)j\', \'$1an\'),\n        (r\'(\\w)k\', \'$1ao\'), (r\'(\\w)l\', \'$1ai\'), (r\'(\\w)z\', \'$1ei\'),\n        (r\'(\\w)x\', \'$1ie\'), (r\'(\\w)c\', \'$1iao\'), (r\'([dtgkhvuirzcs])v\', \'$1ui\'),\n        (r\'(\\w)b\', \'$1ou\'), (r\'(\\w)m\', \'$1ian\'), (r\'([aoe])\\1(\\w)\', \'$1$2\'),\n        (r\'^v\', \'zh\'), (r\'^i\', \'ch\'), (r\'^u\', \'sh\'),\n        (r\'([jqxy])v\', \'$1u\'), (r\'([nl])v\', \'$1ü\'),\n    ]),\n    _R([  # 3: 微软 (ing 在 ; 键)\n        (r\'([aoe])(\\w)\', \'0$2\'), (r\'([bpmnljqxy])n\', \'$1in\'), (r\'(\\w)g\', \'$1eng\'),\n        (r\'(\\w)q\', \'$1iu\'), (r\'([gkhvuirzcs])w\', \'$1ua\'), (r\'(\\w)w\', \'$1ia\'),\n        (r\'([dtnlgkhjqxyvuirzcs])r\', \'$1uan\'), (r\'0r\', \'er\'), (r\'([dtgkhvuirzcs])v\', \'$1ui\'),\n        (r\'(\\w)v\', \'$1ve\'), (r\'(\\w)t\', \'$1ve\'), (r\'([gkhvuirzcs])y\', \'$1uai\'),\n        (r\'(\\w)y\', \'$1v\'), (r\'([dtnlgkhvuirzcs])o\', \'$1uo\'), (r\'(\\w)p\', \'$1un\'),\n        (r\'([jqx])s\', \'$1iong\'), (r\'(\\w)s\', \'$1ong\'), (r\'([jqxnl])d\', \'$1iang\'),\n        (r\'(\\w)d\', \'$1uang\'), (r\'(\\w)f\', \'$1en\'), (r\'(\\w)h\', \'$1ang\'),\n        (r\'(\\w)j\', \'$1an\'), (r\'(\\w)k\', \'$1ao\'), (r\'(\\w)l\', \'$1ai\'),\n        (r\'(\\w)z\', \'$1ei\'), (r\'(\\w)x\', \'$1ie\'), (r\'(\\w)c\', \'$1iao\'),\n        (r\'(\\w)b\', \'$1ou\'), (r\'(\\w)m\', \'$1ian\'), (r\'(\\w);\', \'$1ing\'),\n        (r\'0(\\w)\', \'$1\'), (r\'^v\', \'zh\'), (r\'^i\', \'ch\'),\n        (r\'^u\', \'sh\'), (r\'([jqxy])v\', \'$1u\'), (r\'([nl])v\', \'$1ü\'),\n    ]),\n]\n\n\ndef sp_segment(seg, scheme):\n    """一个两键音节 -> 全拼 (与 C# SpSegment 一致)"""\n    for pat, rep in SP_RULES[scheme - 1]:\n        seg = pat.sub(rep, seg)\n    if len(seg) == 2 and seg[0] == seg[1] and seg[0] in \'aoe\':\n        seg = seg[:1]                                # 零声母单韵母: aa/oo/ee -> a/o/e\n    if scheme != 1 and seg == \'r\':\n        seg = \'er\'                                   # 自然码/微软: er 单击 r\n    return seg.replace(\'ü\', \'v\')   # 码表约定: lü->lv, lüe->lve (略/虐); 不要 \'üe->ue\'(会撞 lue 蓼/庐 码)\n\n\ndef shuangpin_expand(keys, scheme):\n    """双拼键串 -> 全拼前缀 (与 C# ShuangpinExpand 一致)"""\n    if scheme < 1 or scheme > 3 or not keys:\n        return keys\n    sb = []\n    i = 0\n    while i < len(keys):\n        n = 2 if i + 1 < len(keys) else 1\n        sb.append(sp_segment(keys[i:i + n], scheme))\n        i += n\n    return \'\'.join(sb)\n\nCN_DIGIT = \'零壹贰叁肆伍陆柒捌玖\'\nCN_UNIT4 = (\'\', \'拾\', \'佰\', \'仟\')\nCN_BIG = (\'\', \'万\', \'亿\', \'兆\', \'京\')\n\n\ndef upper_amount(ds):\n    """1234 -> 壹仟贰佰叁拾肆元整 (与 C# UpperAmount 一致)"""\n    s = ds.lstrip(\'0\')\n    if not s:\n        return \'零元整\'\n    if len(s) > 16:\n        return None\n    head = len(s) % 4 or 4\n    groups = (len(s) - head) // 4 + 1\n    sb = []\n    pending_zero = False\n    for g in range(groups):\n        start = 0 if g == 0 else head + (g - 1) * 4\n        ln = head if g == 0 else 4\n        grp = s[start:start + ln]\n        if all(c == \'0\' for c in grp):\n            pending_zero = True\n            continue\n        if g > 0 and pending_zero and sb:\n            sb.append(\'零\')\n        pending_zero = False\n        grp_zero = False\n        for i, ch in enumerate(grp):\n            d = ord(ch) - 48\n            if d == 0:\n                grp_zero = True\n                continue\n            if grp_zero:\n                sb.append(\'零\')\n                grp_zero = False\n            sb.append(CN_DIGIT[d])\n            sb.append(CN_UNIT4[len(grp) - 1 - i])\n        if g < groups - 1:\n            sb.append(CN_BIG[groups - 1 - g])\n    sb.append(\'元整\')\n    return \'\'.join(sb)\n\n\ndef thousands(ds):\n    """1234567 -> 1,234,567"""\n    s = ds.lstrip(\'0\') or \'0\'\n    out = []\n    for i, ch in enumerate(s):\n        out.append(ch)\n        left = len(s) - 1 - i\n        if left > 0 and left % 3 == 0:\n            out.append(\',\')\n    return \'\'.join(out)\n\n\ndef vmode_candidates(code):\n    """v+数字 -> [大写金额, 千分位] (与 AddVMode 一致: 大写在前)"""\n    if len(code) < 2 or code[0] != \'v\':\n        return []\n    ds = code[1:]\n    if not ds.isdigit() or len(ds) > 16:\n        return []\n    out = []\n    up = upper_amount(ds)\n    if up is not None:\n        out.append(up)\n    out.append(thousands(ds))\n    return out\n\n\ndef dynamic_candidates(code):\n    """rq/sj/xq 动态候选 (与 AddDynamic 一致)"""\n    n = time.localtime()\n    if code == \'rq\':\n        return [time.strftime(\'%Y-%m-%d\', n), \'%d年%d月%d日\' % (n.tm_year, n.tm_mon, n.tm_mday), time.strftime(\'%Y/%m/%d\', n)]\n    if code == \'sj\':\n        return [time.strftime(\'%H:%M\', n), time.strftime(\'%H:%M:%S\', n), time.strftime(\'%Y-%m-%d %H:%M\', n)]\n    if code == \'xq\':\n        w = \'日一二三四五六\'[(n.tm_wday + 1) % 7]\n        return [\'星期\' + w, \'周\' + w]\n    return []\n\n\ndef is_all_cjk(s):\n    return all(\'\\u4e00\' <= c <= \'\\u9fff\' for c in s)\n\n\n# ---------- config.txt (与 C# LoadConfig 同格式) ----------\nDEFAULT_LEARN_K = 5000   # 全量学习词频排序权重 (config learnk, 默认)\nDEFAULT_RECENT_K = 200   # 近期热度排序权重 (config recentk, 默认)\n\n\ndef load_config(path):\n    """解析 config.txt 返回 dict(与 C# LoadConfig 同格式):\n    fuzzy/showcode/hideidle/shuangpin/trad/sentence/assoc/starton/apps/paste/keyfix/\n    followcaret/theme/learnk/recentk/phrases."""\n    cfg = dict(fuzzy=list(FUZZY_PAIRS), showcode=False, hideidle=True, shuangpin=0,\n               trad=False, sentence=True, assoc=True, starton=True, apps={},\n               paste=3, keyfix=True, followcaret=True, theme=\'dark\',\n               learnk=DEFAULT_LEARN_K, recentk=DEFAULT_RECENT_K)\n    try:\n        with open(path, encoding=\'utf-8\') as f:\n            for raw in f:\n                t = raw.strip()\n                if not t or t[0] in \'#;\':\n                    continue\n                eq = t.find(\'=\')\n                if eq < 1:\n                    continue\n                k = t[:eq].strip().lower()\n                v = t[eq + 1:].strip()\n                if k == \'fuzzy\':\n                    if not v or v in (\'none\', \'off\'):\n                        cfg[\'fuzzy\'] = []\n                    else:\n                        pairs = []\n                        for pair in v.split(\',\'):\n                            d = pair.find(\'-\')\n                            if 0 < d < len(pair) - 1:\n                                pairs.append((pair[:d].strip(), pair[d + 1:].strip()))\n                        if pairs:\n                            cfg[\'fuzzy\'] = pairs\n                elif k == \'showcode\':\n                    cfg[\'showcode\'] = v in (\'1\', \'on\', \'true\')\n                elif k == \'hideidle\':\n                    cfg[\'hideidle\'] = v in (\'1\', \'on\', \'true\')\n                elif k == \'shuangpin\':\n                    cfg[\'shuangpin\'] = {\'xiaohe\': 1, \'小鹤\': 1, \'flypy\': 1, \'ziranma\': 2, \'自然码\': 2,\n                                        \'zrm\': 2, \'ms\': 3, \'微软\': 3, \'mspy\': 3}.get(v, 0)\n                elif k == \'trad\':\n                    cfg[\'trad\'] = v in (\'1\', \'on\', \'true\')\n                elif k == \'sentence\':\n                    cfg[\'sentence\'] = v not in (\'0\', \'off\', \'false\')\n                elif k == \'assoc\':\n                    cfg[\'assoc\'] = v not in (\'0\', \'off\', \'false\')\n                elif k == \'starton\':\n                    cfg[\'starton\'] = v in (\'1\', \'on\', \'true\')\n                elif k == \'paste\':\n                    cfg[\'paste\'] = {\'on\': 1, \'always\': 1, \'off\': 2, \'key\': 3, \'unicode\': 3}.get(v, 0)\n                elif k == \'keyfix\':\n                    cfg[\'keyfix\'] = v in (\'1\', \'on\', \'true\')\n                elif k == \'learnk\':\n                    try:\n                        cfg[\'learnk\'] = max(0, int(v))\n                    except ValueError:\n                        pass\n                elif k == \'recentk\':\n                    try:\n                        cfg[\'recentk\'] = max(0, int(v))\n                    except ValueError:\n                        pass\n                elif k == \'followcaret\':\n                    cfg[\'followcaret\'] = v not in (\'0\', \'off\', \'false\')\n                elif k == \'theme\':\n                    cfg[\'theme\'] = \'light\' if v.lower() in (\'light\', \'浅色\', \'白\') else \'dark\'\n                elif k == \'phrase\':\n                    sp = v.find(\'\\t\')\n                    if sp < 1:\n                        sp = v.find(\' \')\n                    if sp > 0:\n                        cfg.setdefault(\'phrases\', {})[v[:sp].strip().lower()] = v[sp + 1:].strip()\n                elif k == \'app\':\n                    ap = v.split(\'\\t\')\n                    if len(ap) >= 3:\n                        code, name, cmd = ap[0], ap[1], ap[2]\n                        args = ap[3] if len(ap) > 3 else \'\'\n                    else:\n                        m = re.match(r\'^(\\S+)\\s+(\\S+)\\s+("(?:[^"]*)"|\\\'[^\\\']*\\\'|\\S+)(?:\\s+(.*))?$\', v)\n                        if not m:\n                            continue\n                        code, name, cmd, args = m.group(1), m.group(2), m.group(3).strip(\'"\\\'\'), m.group(4) or \'\'\n                    code = code.strip().lower()\n                    if code:\n                        cfg[\'apps\'][code] = (name.strip(), os.path.expandvars(cmd.strip()), os.path.expandvars(args.strip()))\n    except OSError:\n        pass\n    return cfg\n\n\ndef parse_dict(path):\n    """code -> space-joined words (与 AddDictLine 一致: 小写 code, 后段原样)."""\n    d = {}\n    try:\n        with open(path, encoding=\'utf-8\') as f:\n            for raw in f:\n                t = raw.strip()\n                if len(t) < 3:\n                    continue\n                sp = t.find(\' \')\n                if sp < 1:\n                    continue\n                k = t[:sp].strip().lower()\n                v = t[sp + 1:].strip()\n                if k and v:\n                    d[k] = v\n    except OSError:\n        pass\n    return d\n\n\ndef build_sorted(d):\n    ks = sorted(d.keys())              # Python str 比较 = ordinal (BMP)\n    return ks, [d[k] for k in ks]\n\n\ndef overlay_import(target, imp):\n    """C# OverlayImport 语义: 已有候选保持优先, 新候选追加去重 (import_*.txt 叠加)."""\n    for k, v in imp.items():\n        cur = target.get(k)\n        if cur is None:\n            target[k] = v\n        else:\n            existing = set(cur.split(\' \'))\n            for w in v.split(\' \'):\n                if w and w not in existing:\n                    cur = cur + \' \' + w\n                    existing.add(w)\n            target[k] = cur\n\n\ndef build_char_py(py):\n    """char -> [pinyin...] (按 key 排序遍历, 与 BuildCharPy 一致)"""\n    char_py = {}\n    for code in sorted(py.keys()):\n        for w in py[code].split(\' \'):\n            if len(w) == 1:\n                lst = char_py.setdefault(w, [])\n                if code not in lst:\n                    lst.append(code)\n    return char_py\n\n\ndef build_acro(py, char_py):\n    """简拼: 词每字首字母 -> [words] (与 BuildAcro 一致, 每 key 上限 60)"""\n    acro = {}\n    for code in sorted(py.keys()):\n        for w in py[code].split(\' \'):\n            if len(w) < 2:\n                continue\n            ini = []\n            ok = True\n            for ch in w:\n                ps = char_py.get(ch)\n                if ps:\n                    ini.append(ps[0][0])\n                else:\n                    ok = False\n                    break\n            if not ok:\n                continue\n            lst = acro.setdefault(\'\'.join(ini), [])\n            if len(lst) < 60 and w not in lst:\n                lst.append(w)\n    return acro\n\n\ndef build_reverse(ec):\n    """CN word -> EN words (BuildReverse: 每词上限 8)"""\n    rev = {}\n    for en in sorted(ec.keys()):\n        for cn in ec[en].split(\' \'):\n            if not cn:\n                continue\n            lst = rev.setdefault(cn, [])\n            if len(lst) < 8 and en not in lst:\n                lst.append(en)\n    return {k: \' \'.join(v) for k, v in rev.items()}\n\n\n# ---------- 码表导入 (转换常见码表 -> import_py/wb/ec.txt, 对齐 C# ImportCodeTable) ----------\ndef is_pure_ascii(s):\n    return bool(s) and all(ord(c) <= 0x7F for c in s)\n\n\ndef is_all_digits(s):\n    return bool(s) and all(\'0\' <= c <= \'9\' for c in s)\n\n\ndef valid_code(s):\n    """^[a-z][a-z0-9\']{0,31}$"""\n    if not s or len(s) > 32 or not (\'a\' <= s[0] <= \'z\'):\n        return False\n    return all((\'a\' <= c <= \'z\') or (\'0\' <= c <= \'9\') or c == "\'" for c in s[1:])\n\n\ndef skip_line(t):\n    """空 / # ; // --- ... / yaml \'key: value\' 头"""\n    t = t.strip()\n    if not t:\n        return True\n    if t[0] in (\'#\', \';\') or t.startswith(\'//\') or t.startswith(\'---\') or t.startswith(\'...\'):\n        return True\n    ci = t.find(\':\')\n    return ci > 0 and (ci + 1 == len(t) or t[ci + 1] in (\' \', \'\\t\'))\n\n\ndef read_import_text(path):\n    """读文件: 先按大小预检(>64MB 直接 None), 再 UTF-8 -> GB18030 -> GBK; 用 with 关句柄."""\n    try:\n        if os.path.getsize(path) > 64 * 1024 * 1024:\n            return None\n        with open(path, \'rb\') as f:\n            b = f.read()\n        for enc in (\'utf-8\', \'gb18030\', \'gbk\'):\n            try:\n                return b.decode(enc)\n            except (UnicodeDecodeError, LookupError):\n                continue\n        return b.decode(\'utf-8\', \'replace\')\n    except OSError:\n        return None\n\n\ndef detect_format(lines):\n    """1 = 词在前(Rime), 2 = 码在前, 0 = 未检测"""\n    word_first = code_first = seen = 0\n    for raw in lines:\n        if seen >= 200:\n            break\n        t = raw.strip()\n        if not t or skip_line(t):\n            continue\n        seen += 1\n        if \'\\t\' in t:\n            word_first += 1\n            continue\n        sp = t.find(\' \')\n        if sp < 1:\n            continue\n        if is_pure_ascii(t[:sp]):\n            code_first += 1\n        else:\n            word_first += 1\n    if word_first == 0 and code_first == 0:\n        return 0\n    return 1 if word_first >= code_first else 2\n\n\ndef convert_file(text, fmt, acc):\n    """转换并追加到 acc {code: [words]}; 返回 (skipped, trunc_codes, trunc_total)"""\n    skipped = trunc_codes = trunc_total = 0\n    for raw in text.split(\'\\n\'):\n        t = raw.strip()\n        if not t or skip_line(t):\n            continue\n        tab = \'\\t\' in t\n        fs = [f.strip() for f in (t.split(\'\\t\') if tab else t.split(\' \')) if f.strip()]\n        if len(fs) < 2:\n            skipped += 1\n            continue\n        if is_all_digits(fs[-1]):\n            fs = fs[:-1]                                # 尾权重字段\n        if len(fs) < 2:\n            skipped += 1\n            continue\n        code = None\n        words = []\n        if fmt == 1:                                    # 词在前: word code [weight]\n            cd = fs[1].strip().lower()\n            if valid_code(cd):\n                code = cd\n                words.append(fs[0])\n            elif is_pure_ascii(fs[0]) and valid_code(fs[0].lower()):   # EN word + CN meanings\n                code = fs[0].strip().lower()\n                words = [w for w in fs[1:] if w]\n            else:\n                skipped += 1\n                continue\n        else:                                           # 码在前: code word word ...\n            cd = fs[0].strip().lower()\n            if not valid_code(cd):\n                skipped += 1\n                continue\n            code = cd\n            words = [w for w in fs[1:] if w]\n        if code is None or not words:\n            skipped += 1\n            continue\n        lst = acc.get(code)\n        if lst is None:\n            if len(acc) >= 500000:\n                trunc_total += 1\n                continue\n            lst = []\n            acc[code] = lst\n        for w in words:\n            if not w or w in lst:\n                continue\n            if \' \' in w:\n                skipped += 1\n                continue\n            if len(lst) >= 300:\n                trunc_codes += 1\n                break\n            lst.append(w)\n    return skipped, trunc_codes, trunc_total\n\n\ndef load_import_base(path):\n    """读现有 import 文件 -> {code: [words]} (重导入幂等)"""\n    acc = {}\n    try:\n        with open(path, encoding=\'utf-8\') as f:\n            for raw in f:\n                t = raw.strip()\n                if len(t) < 3:\n                    continue\n                sp = t.find(\' \')\n                if sp < 1:\n                    continue\n                k = t[:sp].strip().lower()\n                lst = []\n                for w in t[sp + 1:].split(\' \'):\n                    if w and w not in lst:\n                        lst.append(w)\n                if k and lst:\n                    acc[k] = lst\n    except OSError:\n        pass\n    return acc\n\n\ndef write_import_file(path, acc):\n    """写 import 文件: \'code w1 w2 ...\' 每行, 按 code 排序, UTF-8 无 BOM"""\n    with open(path, \'w\', encoding=\'utf-8\') as f:\n        for k in sorted(acc.keys()):\n            f.write(k)\n            for w in acc[k]:\n                f.write(\' \' + w)\n            f.write(\'\\n\')\n\n\ndef suggest_target(file_name):\n    """0=五笔 1=拼音 2=英汉"""\n    n = (file_name or \'\').lower()\n    if \'wubi\' in n or \'五笔\' in n or n.startswith(\'wb\') or \'_wb\' in n or \'-wb\' in n:\n        return 0\n    if \'english\' in n or \'英汉\' in n or n.startswith(\'ec\') or \'_ec\' in n or \'-ec\' in n:\n        return 2\n    if \'pinyin\' in n or \'拼音\' in n or \'双拼\' in n or \'全拼\' in n or n.startswith(\'py\') or \'_py\' in n or \'-py\' in n:\n        return 1\n    if n.endswith(\'.yaml\') or n.endswith(\'.yml\') or n.endswith(\'.dict\'):\n        return 0\n    return 1\n\n\ndef fuzzy_variants(code):\n    """单替换模糊音, 上限 16 (与 FuzzyVariants 一致)"""\n    seen = set()\n    out = []\n    made = 0\n    for pr in FUZZY_PAIRS:\n        for side in range(2):\n            frm, to = pr[side], pr[1 - side]\n            pos = 0\n            while made < 16:\n                at = code.find(frm, pos)\n                if at < 0:\n                    break\n                pos = at + 1\n                v = code[:at] + to + code[at + len(frm):]\n                if v not in seen:\n                    seen.add(v)\n                    out.append(v)\n                    made += 1\n    return out\n\n\ndef _atomic_write(path, text):\n    """原子写文本(先 .tmp 再 os.replace), 避免写盘中断损坏关键数据文件."""\n    tmp = path + \'.tmp\'\n    try:\n        with open(tmp, \'w\', encoding=\'utf-8\') as f:\n            f.write(text)\n        os.replace(tmp, path)\n    except OSError:\n        try:\n            os.remove(tmp)\n        except OSError:\n            pass\n\n\nclass Engine:\n    CACHE_VER = 1\n\n    def _paths(self):\n        ps = [os.path.join(self.dict_dir, n) for n in (\'py.txt\', \'wb.txt\', \'ec.txt\', \'trad.txt\')]\n        ps += [os.path.join(self.dict_dir, n) for n in (\'import_py.txt\', \'import_wb.txt\', \'import_ec.txt\')]\n        return ps\n\n    def _build(self):\n        self.py = parse_dict(os.path.join(self.dict_dir, \'py.txt\'))\n        self.wb = parse_dict(os.path.join(self.dict_dir, \'wb.txt\'))\n        self.ec = parse_dict(os.path.join(self.dict_dir, \'ec.txt\'))\n        overlay_import(self.py, parse_dict(os.path.join(self.dict_dir, \'import_py.txt\')))\n        overlay_import(self.wb, parse_dict(os.path.join(self.dict_dir, \'import_wb.txt\')))\n        overlay_import(self.ec, parse_dict(os.path.join(self.dict_dir, \'import_ec.txt\')))\n        self.pk, self.pv = build_sorted(self.py)\n        self.wk, self.wv = build_sorted(self.wb)\n        self.ek, self.ev = build_sorted(self.ec)\n        self.char_py = build_char_py(self.py)\n        self.acro = build_acro(self.py, self.char_py)\n        self.ce = build_reverse(self.ec)\n\n    def _build_wb_len(self):\n        """五笔码按长度分桶(用于 z 通配等长查询, 替代全表线性扫描)."""\n        self.wb_by_len = {}\n        for k in self.wb:\n            self.wb_by_len.setdefault(len(k), []).append(k)\n\n    def __init__(self, dict_dir, data_dir):\n        t0 = time.time()\n        self.data_dir = data_dir\n        self.dict_dir = dict_dir\n        self.learn_k = DEFAULT_LEARN_K   # 全量学习词频排序权重 (config learnk, main.py 覆盖)\n        self.recent_k = DEFAULT_RECENT_K  # 近期热度排序权重 (config recentk)\n        os.makedirs(data_dir, exist_ok=True)\n        if not self._load_cache(self._paths()):\n            self._build()\n            self._save_cache(self._paths())\n        self.load_ms = (time.time() - t0) * 1000\n        self._init_state()\n\n    def _merge_user_words(self):\n        """把 userwords.txt 合并进 self.py 并重建索引 (启动/热重载共用, 避免导入码表后丢用户词)."""\n        if not self.user_words:\n            return\n        for w, c in self.user_words.items():\n            cur = self.py.get(c)\n            if cur:\n                if (\' \' + cur + \' \').find(\' \' + w + \' \') < 0:\n                    self.py[c] = cur + \' \' + w\n            else:\n                self.py[c] = w\n        self.pk, self.pv = build_sorted(self.py)\n\n    def reload(self):\n        """导入码表后热重载: 重建索引 + 刷新缓存 + 重放用户词(否则已造用户词丢失)."""\n        self._build()\n        self._build_wb_len()\n        self._merge_user_words()\n        self._save_cache(self._paths())\n\n    def _cache_sig(self, paths):\n        return [(os.path.getsize(p), int(os.path.getmtime(p))) if os.path.exists(p) else None for p in paths]\n\n    def _cache_path(self):\n        return os.path.join(self.data_dir, \'dict-cache.pkl\')\n\n    def _load_cache(self, paths):\n        try:\n            import pickle\n            with open(self._cache_path(), \'rb\') as f:\n                obj = pickle.load(f)\n            # 完整性由 sig(码表 mtime/size) + pickle 加载异常保底;\n            # 之前对 95MB data 全量 pickle.dumps 算 md5 严重拖慢启动(~1s+), 已移除\n            if obj.get(\'ver\') != self.CACHE_VER or obj.get(\'sig\') != self._cache_sig(paths):\n                return False\n            (self.py, self.wb, self.ec, self.pk, self.pv, self.wk, self.wv,\n             self.ek, self.ev, self.char_py, self.acro, self.ce) = obj[\'data\']\n            return True\n        except Exception as e:\n            print(\'[wgime] dict-cache load failed: %r\' % (e,), file=sys.stderr)   # 缓存损坏时留痕, 便于排查\n            return False\n\n    def _save_cache(self, paths):\n        try:\n            import pickle\n            obj = {\'ver\': self.CACHE_VER, \'sig\': self._cache_sig(paths),\n                   \'data\': (self.py, self.wb, self.ec, self.pk, self.pv, self.wk, self.wv,\n                            self.ek, self.ev, self.char_py, self.acro, self.ce)}\n            tmp = self._cache_path() + \'.tmp\'\n            with open(tmp, \'wb\') as f:\n                pickle.dump(obj, f, protocol=pickle.HIGHEST_PROTOCOL)\n            os.replace(tmp, self._cache_path())\n        except Exception:\n            pass\n\n    def _init_state(self):\n        # 词频: 分模式桶 + 合并视图\n        self.freq_m = [dict(), dict(), dict()]\n        self.lastpick_m = [dict(), dict(), dict()]\n        self.freq = {}\n        # 近期热度 (滑动窗口): 反映最近使用习惯, 自动过期\n        self.freq_recent = [dict(), dict(), dict()]\n        self.recent_log = deque()\n        self._load_freq()\n        self.freq_dirty = 0\n        self.last_save = time.time()\n        self._save_lock = threading.RLock()   # 词频/联想/近期状态锁(可重入): learn+save_freq 共用, 防保存线程遍历活 dict 时被写侧打断\n        # 用户词 (五笔反查字表: 最长码)\n        self.user_words = self.load_user_words()\n        self._merge_user_words()\n        self.char_wb = {}\n        for code in sorted(self.wb.keys()):\n            if len(code) < 2:\n                continue\n            for w in self.wb[code].split(\' \'):\n                if len(w) == 1 and (w not in self.char_wb or len(code) > len(self.char_wb[w])):\n                    self.char_wb[w] = code\n        self._build_wb_len()   # 五笔 z 通配: 按码长分桶索引(替代全表线性扫描)\n        # 简拼候选顺序由 candidates() 的统一词频排序决定, 不再预排(避免与排序键不一致)\n        # 造句词频 (pywfreq.txt: word:freq)\n        self.word_freq = {}\n        wtot = 0\n        try:\n            with open(os.path.join(self.dict_dir, \'pywfreq.txt\'), encoding=\'utf-8\') as f:\n                for line in f:\n                    line = line.strip()\n                    c = line.rfind(\':\')\n                    if c < 1:\n                        continue\n                    try:\n                        n = int(line[c + 1:])\n                    except ValueError:\n                        continue\n                    self.word_freq[line[:c]] = n\n                    wtot += n\n        except OSError:\n            pass\n        self.log_total_w = math.log(max(wtot, 1000))\n        # 联想 (commit 二元组)\n        self.assoc = {}\n        self._load_assoc()\n        # 繁简\n        self.trad_map = None\n        tp = os.path.join(self.dict_dir, \'trad.txt\')\n        try:\n            with open(tp, encoding=\'utf-8-sig\') as f:\n                lines = f.read().split(\'\\n\')\n            self.trad_map = {}\n            for i in range(min(len(lines[0]), len(lines[1]))):\n                if lines[0][i] not in self.trad_map:\n                    self.trad_map[lines[0][i]] = lines[1][i]\n        except (OSError, IndexError, UnicodeError):\n            self.trad_map = None\n\n    # ---------- freq / lastpick persistence (与 C# 版同格式, 可互换) ----------\n    def _load_freq(self):\n        for m in range(3):\n            p = os.path.join(self.data_dir, \'userdict_%s.txt\' % MODE_SUFFIX[m])\n            try:\n                with open(p, encoding=\'utf-8\') as f:\n                    for line in f:\n                        sp = line.rstrip(\'\\n\').rfind(\' \')\n                        if sp < 1:\n                            continue\n                        try:\n                            n = int(line[sp + 1:])\n                        except ValueError:\n                            continue\n                        self.freq_m[m][line[:sp]] = n\n            except OSError:\n                pass\n            p = os.path.join(self.data_dir, \'lastpick_%s.txt\' % MODE_SUFFIX[m])\n            try:\n                with open(p, encoding=\'utf-8\') as f:\n                    for line in f:\n                        sp = line.find(\' \')\n                        if sp < 1:\n                            continue\n                        self.lastpick_m[m][line[:sp]] = line[sp + 1:].rstrip(\'\\n\')\n            except OSError:\n                pass\n        for b in self.freq_m:\n            for k, v in b.items():\n                self.freq[k] = self.freq.get(k, 0) + v\n\n    def learn(self, code, w, mode):\n        if not w:\n            return\n        spawn = False\n        with self._save_lock:\n            self.freq[w] = self.freq.get(w, 0) + 1\n            if len(self.freq) > 90000:\n                self.freq.pop(next(iter(self.freq)))\n            if 0 <= mode < 3:\n                fb = self.freq_m[mode]\n                fb[w] = fb.get(w, 0) + 1\n                if len(fb) > 30000:\n                    fb.pop(next(iter(fb)))\n                if code:\n                    lb = self.lastpick_m[mode]\n                    lb[code] = w\n                    if len(lb) > 30000:\n                        lb.pop(next(iter(lb)))\n            self.freq_dirty += 1\n            if self.freq_dirty >= 50 or time.time() - self.last_save >= 5:\n                self.freq_dirty = 0\n                self.last_save = time.time()\n                spawn = True\n        if spawn:\n            threading.Thread(target=self.save_freq, daemon=True).start()\n\n    # ---------- 近期热度 (滑动窗口) + 误学回滚 ----------\n    def touch_recent(self, mode, w):\n        """近期热度: 上屏即计一次; recent_log 超 RE_CAP 时溢出最旧, 自动过期."""\n        if mode >= 3 or not w:\n            return\n        with self._save_lock:\n            self.recent_log.append((mode, w))\n            fr = self.freq_recent[mode]\n            fr[w] = fr.get(w, 0) + 1\n            if len(self.recent_log) > RE_CAP:\n                om, ow = self.recent_log.popleft()\n                n = self.freq_recent[om].get(ow, 0)\n                if n <= 1:\n                    self.freq_recent[om].pop(ow, None)\n                else:\n                    self.freq_recent[om][ow] = n - 1\n\n    def _untouch_recent(self, mode, w):\n        """误学回滚: 从近期窗口移除该词一次."""\n        if mode >= 3 or not w:\n            return\n        with self._save_lock:\n            try:\n                self.recent_log.remove((mode, w))\n            except ValueError:\n                pass\n            n = self.freq_recent[mode].get(w, 0)\n            if n <= 1:\n                self.freq_recent[mode].pop(w, None)\n            else:\n                self.freq_recent[mode][w] = n - 1\n\n    def unlearn(self, w, code, mode):\n        """误学回滚: 撤销一次主动学习 (learn 的逆操作) + 近期窗口回滚."""\n        def dec(d, k):\n            n = d.get(k)\n            if n is None:\n                return\n            if n <= 1:\n                d.pop(k, None)\n            else:\n                d[k] = n - 1\n        with self._save_lock:\n            dec(self.freq, w)\n            if 0 <= mode < 3:\n                dec(self.freq_m[mode], w)\n                lb = self.lastpick_m[mode]\n                if code in lb:\n                    lb.pop(code, None)\n                self._untouch_recent(mode, w)\n            self.freq_dirty += 1   # 消费掉回滚, 触发后续落盘\n\n    # ---------- 造句 (BestSentence: 单字/词一元格架, score=sum(log(f+1))-edges*log_total) ----------\n    def best_sentence(self, code):\n        n = len(code)\n        if n < 4 or n > 32:\n            return None\n        NEG = float(\'-inf\')\n        best = [0.0] + [NEG] * n\n        frm = [0] * (n + 1)\n        word = [\'\'] * (n + 1)\n        for i in range(n):\n            if best[i] == NEG:\n                continue\n            for ln in range(1, min(12, n - i) + 1):\n                val = self.py.get(code[i:i + ln])\n                if val is None:\n                    continue\n                bw, bwf = None, -1\n                for t in val.split(\' \'):\n                    f = self.word_freq.get(t, 0)\n                    if f > bwf:\n                        bwf, bw = f, t\n                if bw is None:\n                    continue\n                sc = best[i] + math.log(bwf + 1) - self.log_total_w\n                if sc > best[i + ln]:\n                    best[i + ln] = sc\n                    frm[i + ln] = i\n                    word[i + ln] = bw\n        if best[n] == NEG:\n            return None\n        parts = []\n        p = n\n        while p > 0:\n            parts.append(word[p])\n            p = frm[p]\n        return \'\'.join(reversed(parts))\n\n    # ---------- 联想 (与 C# Assoc 一致: prev commit -> cur counts) ----------\n    def learn_assoc(self, prev, cur):\n        if not prev or not cur or prev == cur or len(prev) > 8 or len(cur) > 8:\n            return\n        if not is_all_cjk(prev) or not is_all_cjk(cur):\n            return\n        with self._save_lock:\n            m = self.assoc.get(prev)\n            if m is None:\n                if len(self.assoc) >= 20000:\n                    self.assoc.pop(next(iter(self.assoc)))\n                m = {}\n                self.assoc[prev] = m\n            m[cur] = m.get(cur, 0) + 1\n            if len(m) > 12:                              # 超上限: 丢最弱\n                weak = min(m, key=lambda k: m[k])\n                del m[weak]\n            self.freq_dirty += 1\n\n    def get_assoc(self, w, limit=9):\n        m = self.assoc.get(w)\n        if not m:\n            return []\n        return [k for k, _ in sorted(m.items(), key=lambda kv: -kv[1])[:limit]]\n\n    def _load_assoc(self):\n        try:\n            with open(os.path.join(self.data_dir, \'assoc.txt\'), encoding=\'utf-8\') as f:\n                for line in f:\n                    tab = line.find(\'\\t\')\n                    if tab < 1:\n                        continue\n                    m = {}\n                    for t in line[tab + 1:].strip().split(\' \'):\n                        c = t.rfind(\':\')\n                        if c < 1:\n                            continue\n                        try:\n                            m[t[:c]] = int(t[c + 1:])\n                        except ValueError:\n                            pass\n                    if m:\n                        self.assoc[line[:tab]] = m\n        except OSError:\n            pass\n\n    def _save_assoc(self):\n        try:\n            snap = sorted(self.assoc.items(), key=lambda kv: -sum(kv[1].values()))[:20000]\n            with open(os.path.join(self.data_dir, \'assoc.txt\'), \'w\', encoding=\'utf-8\') as f:\n                for k, m in snap:\n                    tops = sorted(m.items(), key=lambda kv: -kv[1])[:8]\n                    f.write(\'%s\\t%s\\n\' % (k, \' \'.join(\'%s:%d\' % (w, c) for w, c in tops)))\n        except OSError:\n            pass\n\n    def save_freq(self):\n        # 锁内做快照(防 UI 线程 learn/learn_assoc 并发写被打断), 锁外写盘(写盘不阻塞学习)\n        try:\n            with self._save_lock:\n                snaps = []\n                lasts = []\n                for m in range(3):\n                    snaps.append(sorted(self.freq_m[m].items(), key=lambda kv: -kv[1])[:20000])\n                    lasts.append(list(self.lastpick_m[m].items())[:20000])\n                assoc_snap = sorted(self.assoc.items(), key=lambda kv: -sum(kv[1].values()))[:20000]\n        except (OSError, RuntimeError, ValueError):\n            return\n        try:\n            for m in range(3):\n                with open(os.path.join(self.data_dir, \'userdict_%s.txt\' % MODE_SUFFIX[m]), \'w\', encoding=\'utf-8\') as f:\n                    for k, v in snaps[m]:\n                        f.write(\'%s %d\\n\' % (k, v))\n                with open(os.path.join(self.data_dir, \'lastpick_%s.txt\' % MODE_SUFFIX[m]), \'w\', encoding=\'utf-8\') as f:\n                    for k, v in lasts[m]:\n                        f.write(\'%s %s\\n\' % (k, v))\n            with open(os.path.join(self.data_dir, \'assoc.txt\'), \'w\', encoding=\'utf-8\') as f:\n                for k, m in assoc_snap:\n                    tops = sorted(m.items(), key=lambda kv: -kv[1])[:8]\n                    f.write(\'%s\\t%s\\n\' % (k, \' \'.join(\'%s:%d\' % (w, c) for w, c in tops)))\n        except OSError:\n            pass\n\n    # ---------- candidate assembly (对齐 ShowCharatar) ----------\n    def candidates(self, keys, mode, py_code=None):\n        """返回 (cands, exact_wubi, extendable). py_code: 双拼展开后的全拼 (mode<2 拼音侧用).\n        造句/动态rq/vf/应用启动/短语在 wgime.py refresh 层."""\n        if py_code is None:\n            py_code = keys\n        cands = []\n        exact_wubi = [False]\n        extendable = [False]\n\n        def add(val):\n            for t in val.split(\' \'):\n                if len(cands) >= CAND_CAP:\n                    break\n                if t and t not in cands:\n                    cands.append(t)\n\n        def add_from_dict(d, ks, vs, is_wubi, code):\n            exact = d.get(code)\n            if exact is not None:\n                if is_wubi:\n                    exact_wubi[0] = True\n                add(exact)\n            i = bisect.bisect_left(ks, code)\n            while i < len(ks) and ks[i].startswith(code) and len(cands) < CAND_CAP:\n                if ks[i] != code:\n                    extendable[0] = True\n                    for t in vs[i].split(\' \'):      # 前缀匹配: 只收单字\n                        if len(cands) >= CAND_CAP:\n                            break\n                        if len(t) == 1 and t not in cands:\n                            cands.append(t)\n                i += 1\n\n        if not keys:\n            return cands, False, False\n        if mode == 0:\n            add_from_dict(self.wb, self.wk, self.wv, True, keys)\n            add_from_dict(self.py, self.pk, self.pv, False, py_code)\n            add_from_dict(self.ec, self.ek, self.ev, False, keys)   # 英汉 (vest->背心)\n        elif mode == 1:\n            add_from_dict(self.py, self.pk, self.pv, False, py_code)\n            add_from_dict(self.ec, self.ek, self.ev, False, keys)   # 英汉\n        elif mode == 2:\n            add_from_dict(self.wb, self.wk, self.wv, True, keys)\n        else:\n            # 词典: EN->CN exact + 前缀, CN->EN 经全拼/简拼反查\n            exact = self.ec.get(keys)\n            if exact is not None:\n                add(exact)\n            i = bisect.bisect_left(self.ek, keys)\n            while i < len(self.ek) and self.ek[i].startswith(keys) and len(cands) < CAND_CAP:\n                if self.ek[i] != keys:\n                    first = self.ev[i].split(\' \')[0]\n                    if first and first not in cands:\n                        cands.append(first)\n                i += 1\n            cn_words = []\n            exact = self.py.get(keys)\n            if exact:\n                for w in exact.split(\' \'):\n                    if w not in cn_words:\n                        cn_words.append(w)\n            for w in self.acro.get(keys, []):\n                if w not in cn_words:\n                    cn_words.append(w)\n            for cn in cn_words:\n                en = self.ce.get(cn)\n                if en:\n                    add(en)\n        if mode < 2:\n            for w in self.acro.get(py_code, []):\n                if len(cands) >= CAND_CAP:\n                    break\n                if len(py_code) >= 2 and w not in cands:\n                    cands.append(w)\n            if len(cands) < PAGE_SIZE:\n                for v in fuzzy_variants(py_code):\n                    exact = self.py.get(v)\n                    if exact:\n                        add(exact)\n                    if len(cands) >= CAND_CAP:\n                        break\n        # 字频排序 (稳定): 语料先验 word_freq + 全量学习词频×learn_k + 近期热度×recent_k\n        # → 常见词天然靠前; 主动选过的词(learn)往上顶; 最近常打的词(近期滑动窗口)也靠前\n        fb = self.freq_m[mode] if mode < 3 else self.freq\n        fr = self.freq_recent[mode] if mode < 3 else {}\n        if len(cands) > 1 and (fb or self.word_freq or fr):\n            cands = sorted(cands, key=lambda w: -(\n                self.word_freq.get(w, 0)\n                + fb.get(w, 0) * self.learn_k\n                + fr.get(w, 0) * self.recent_k))\n        if len(cands) > 1 and mode < 3:\n            lp = self.lastpick_m[mode].get(keys)\n            if lp and lp in cands:\n                cands.remove(lp)\n                cands.insert(0, lp)\n        # 五笔 z 通配 (仅纯五笔模式, 追加在最后, 不参与排序) —— 用码长分桶索引, 只扫等长桶\n        if mode == 2 and \'z\' in keys:\n            for k in self.wb_by_len.get(len(keys), []):\n                if len(cands) >= CAND_CAP:\n                    break\n                ok = True\n                for i, ch in enumerate(k):\n                    if keys[i] != \'z\' and ch != keys[i]:\n                        ok = False\n                        break\n                if ok:\n                    for t in self.wb[k].split(\' \'):\n                        if len(cands) >= CAND_CAP:\n                            break\n                        if t and t not in cands:\n                            cands.append(t)\n        return cands, exact_wubi[0], extendable[0]\n\n    def to_trad(self, s, enabled):\n        if not enabled or not self.trad_map or not s:\n            return s\n        return \'\'.join(self.trad_map.get(c, c) for c in s)\n\n    # ---------- 用户词 (与 C# AddUserWord/LoadUserWords 同格式) ----------\n    def load_user_words(self):\n        uw = {}\n        try:\n            with open(os.path.join(self.data_dir, \'userwords.txt\'), encoding=\'utf-8\') as f:\n                for raw in f:\n                    t = raw.strip()\n                    sp = t.find(\' \')\n                    if sp < 1:\n                        continue\n                    for w in t[sp + 1:].split(\' \'):\n                        if w:\n                            uw[w] = t[:sp]\n        except OSError:\n            pass\n        return uw\n\n    def save_user_words(self):\n        try:\n            by_code = {}\n            for w, c in self.user_words.items():\n                by_code.setdefault(c, []).append(w)\n            text = \'\'.join(\'%s %s\\n\' % (c, \' \'.join(ws)) for c, ws in by_code.items())\n            _atomic_write(os.path.join(self.data_dir, \'userwords.txt\'), text)   # 原子写, 防损坏\n        except OSError:\n            pass\n\n    def code_for(self, w):\n        """全拼码 (CodeFor: 每字取第一个拼音)"""\n        out = []\n        for ch in w:\n            ps = self.char_py.get(ch)\n            if not ps:\n                return None\n            out.append(ps[0])\n        return \'\'.join(out)\n\n    def wubi_code_for(self, w):\n        """五笔 86 构词码 (WubiCodeFor)"""\n        n = len(w)\n        if n < 2:\n            return None\n        cs = []\n        for ch in w:\n            c = self.char_wb.get(ch)\n            if not c:\n                return None\n            cs.append(c)\n        if n == 2:\n            return cs[0][:2] + cs[1][:2]\n        if n == 3:\n            return cs[0][0] + cs[1][0] + cs[2][:2]\n        return cs[0][0] + cs[1][0] + cs[2][0] + cs[n - 1][0]\n\n    def add_user_word(self, word, code):\n        """造词: 进拼音表 + 排序数组重建 + 简拼索引 + 五笔表 (双注册)"""\n        if not code or word in self.user_words:\n            return False\n        cur = self.py.get(code)\n        if cur and (\' \' + cur + \' \').find(\' \' + word + \' \') >= 0:\n            return False\n        self.user_words[word] = code\n        self.py[code] = (cur + \' \' + word) if cur else word\n        self.pk, self.pv = build_sorted(self.py)\n        wbc = self.wubi_code_for(word)\n        if wbc:\n            curw = self.wb.get(wbc)\n            if not (curw and (\' \' + curw + \' \').find(\' \' + word + \' \') >= 0):\n                self.wb[wbc] = (curw + \' \' + word) if curw else word\n                self.wk, self.wv = build_sorted(self.wb)\n        ini = []\n        ok = True\n        for ch in word:\n            ps = self.char_py.get(ch)\n            if ps:\n                ini.append(ps[0][0])\n            else:\n                ok = False\n                break\n        if ok:\n            lst = self.acro.setdefault(\'\'.join(ini), [])\n            if word not in lst:\n                lst.append(word)\n        self.save_user_words()\n        return True\n', 'plugins': '# -*- coding: utf-8 -*-\n"""wgime-py plugins: plugins/*.txt parsing + step DSL executor + csharp dispatch.\n\n文件格式 (与 WgIme 插件规范一致):\n  code = xx / name = 名称 / desc = 说明  (头部)\n  之后: 步骤 DSL 或 [csharp] ... [/csharp] 块\n"""\nimport glob\nimport hashlib\nimport os\nimport re\nimport shlex\nimport shutil\nimport subprocess\nimport tempfile\nimport time\nimport winreg\n\n\nclass Plugin(object):\n    def __init__(self, path):\n        self.path = path\n        self.code = None\n        self.name = None\n        self.desc = \'\'\n        self.version = \'\'\n        self.author = \'\'\n        self.requires = \'\'\n        self.perm = \'low\'     # 权限等级: low/network/run/registry/destructive\n        self.kind = \'steps\'      # \'steps\' | \'csharp\' | \'python\'\n        self.body = \'\'\n        self.error = None\n\n\ndef parse_plugin(path):\n    p = Plugin(path)\n    try:\n        text = open(path, encoding=\'utf-8\').read()\n    except OSError as e:\n        p.error = str(e)\n        return p\n    m = re.search(r\'(?s)\\[csharp\\]\\s*(.*?)\\[/csharp\\]\', text)\n    if m:\n        p.kind = \'csharp\'\n        p.body = m.group(1)\n    mp = re.search(r\'(?s)\\[python\\]\\s*(.*?)\\[/python\\]\', text)\n    if mp:\n        p.kind = \'python\'                                # [python] 块: 纯 Python 代码 (替代 [csharp])\n        p.body = mp.group(1)\n    # 头部: code/name/desc (第一个非"键=值"非注释行起为步骤区)\n    lines = text.split(\'\\n\')\n    body_start = None\n    for i, line in enumerate(lines):\n        t = line.strip()\n        if not t or t[0] in \';#\':\n            continue\n        mm = re.match(r\'^(code|name|desc|version|author|requires|perm)\\s*[=:]\\s*(.*)$\', t, re.I)\n        if mm:\n            k = mm.group(1).lower()\n            v = mm.group(2).strip()\n            if k == \'code\' and p.code is None:\n                p.code = v.lower()\n            elif k == \'name\' and p.name is None:\n                p.name = v\n            elif k == \'desc\':\n                p.desc = v\n            elif k == \'version\':\n                p.version = v\n            elif k == \'author\':\n                p.author = v\n            elif k == \'requires\':\n                p.requires = v\n            elif k == \'perm\':\n                p.perm = v.lower()\n            continue\n        body_start = i\n        break\n    if p.kind == \'steps\':\n        p.body = \'\\n\'.join(lines[body_start:]) if body_start is not None else \'\'\n    if not p.code or not p.name:\n        p.error = \'missing code/name\'\n    return p\n\n\ndef load_plugins(plugin_dir, data_dir):\n    """返回 (plugins, disabled_codes)"""\n    plugins = []\n    disabled = set()\n    try:\n        with open(os.path.join(data_dir, \'plugins-disabled.txt\'), encoding=\'utf-8\') as f:\n            disabled = set(l.strip() for l in f if l.strip())\n    except OSError:\n        pass\n    for path in sorted(glob.glob(os.path.join(plugin_dir, \'*.txt\'))):\n        p = parse_plugin(path)\n        if p.error:\n            continue\n        p.enabled = os.path.basename(p.path) not in disabled\n        plugins.append(p)\n    return plugins, disabled\n\n\ndef save_disabled(data_dir, disabled):\n    try:\n        with open(os.path.join(data_dir, \'plugins-disabled.txt\'), \'w\', encoding=\'utf-8\') as f:\n            f.write(\'\\n\'.join(sorted(disabled)))\n    except OSError:\n        pass\n\n\n# ---------- 插件 manifest / 权限 ----------\nHIGH_PERM = (\'network\', \'run\', \'registry\', \'destructive\')\nPERM_LABEL = {\'network\': \'联网\', \'run\': \'执行命令\', \'registry\': \'修改注册表\', \'destructive\': \'删除文件/清理\'}\nDESTRUCTIVE_VERBS = (\'file-del\', \'reg-set\', \'reg-del\', \'kill\')   # 数据破坏/系统级操作: 执行前强确认\n\n\ndef plugin_meta(p):\n    """统一读取插件 manifest, 兼容 .py 模块(属性) 与 .txt Plugin 对象(字段)."""\n    if hasattr(p, \'CODE\'):                       # .py 模块插件\n        code = getattr(p, \'CODE\', \'\')\n        return {\'code\': code, \'name\': getattr(p, \'NAME\', code) or code,\n                \'desc\': getattr(p, \'DESC\', \'\') or \'\', \'version\': str(getattr(p, \'VERSION\', \'\') or \'\'),\n                \'author\': str(getattr(p, \'AUTHOR\', \'\') or \'\'), \'requires\': str(getattr(p, \'REQUIRES\', \'\') or \'\'),\n                \'perm\': str(getattr(p, \'PERM\', \'low\') or \'low\')}\n    # .txt Plugin 对象\n    return {\'code\': p.code or \'\', \'name\': p.name or \'\', \'desc\': p.desc or \'\',\n            \'version\': str(getattr(p, \'version\', \'\') or \'\'), \'author\': str(getattr(p, \'author\', \'\') or \'\'),\n            \'requires\': str(getattr(p, \'requires\', \'\') or \'\'), \'perm\': str(getattr(p, \'perm\', \'low\') or \'low\')}\n\n\ndef is_high_perm(meta):\n    return meta.get(\'perm\', \'low\') in HIGH_PERM\n\n\n# ---------- tools.txt (工具箱) ----------\ndef load_tools(path):\n    """[tab 名] / [cols N] / [按钮名] / code = xx / 步骤行"""\n    tabs = [{\'name\': \'工具\', \'cols\': 2, \'buttons\': []}]\n    btn = None\n    try:\n        with open(path, encoding=\'utf-8\') as f:\n            for raw in f:\n                t = raw.rstrip(\'\\n\')\n                s = t.strip()\n                if not s or s[0] in \';#\':\n                    continue\n                if s.startswith(\'[tab \') and s.endswith(\']\'):\n                    tabs.append({\'name\': s[5:-1].strip(), \'cols\': 2, \'buttons\': []})\n                    btn = None\n                    continue\n                if s.startswith(\'[cols \') and s.endswith(\']\'):\n                    try:\n                        tabs[-1][\'cols\'] = max(1, min(6, int(s[6:-1].strip())))\n                    except ValueError:\n                        pass\n                    continue\n                if s.startswith(\'[\') and s.endswith(\']\') and not re.match(r\'^\\[(shell|cmd|powershell|ps|shellx|psx|/shell|/powershell|/shellx|/psx)\\]$\', s, re.I):\n                    btn = {\'name\': s[1:-1].strip(), \'code\': None, \'steps\': []}\n                    tabs[-1][\'buttons\'].append(btn)\n                    continue\n                m = re.match(r\'^code\\s*=\\s*(\\S+)$\', s, re.I)\n                if m and btn is not None and not btn[\'steps\']:\n                    btn[\'code\'] = m.group(1).lower()\n                    continue\n                if btn is not None:\n                    btn[\'steps\'].append(t)\n    except OSError:\n        pass\n    return [t for t in tabs if t[\'buttons\']]\n\n\n# ---------- 步骤 DSL 执行器 ----------\ndef tokenize(s):\n    """双引号 + %env% 展开"""\n    s = os.path.expandvars(s)\n    out = []\n    cur = \'\'\n    q = False\n    for ch in s:\n        if ch == \'"\':\n            q = not q\n        elif ch == \' \' and not q:\n            if cur:\n                out.append(cur)\n                cur = \'\'\n        else:\n            cur += ch\n    if cur:\n        out.append(cur)\n    return out\n\n\nREG_HIVES = {\'HKCU\': winreg.HKEY_CURRENT_USER, \'HKLM\': winreg.HKEY_LOCAL_MACHINE,\n             \'HKCR\': winreg.HKEY_CLASSES_ROOT, \'HKU\': winreg.HKEY_USERS, \'HKCC\': winreg.HKEY_CURRENT_CONFIG}\n\n\ndef run_steps(body, log, msgbox, confirm):\n    """body: 步骤 DSL 文本. log(msg), msgbox(title,text), confirm(text)->bool"""\n    lines = body.split(\'\\n\')\n    i = 0\n    fails = 0\n    while i < len(lines):\n        t = lines[i].strip()\n        i += 1\n        if not t or t[0] in \';#\':\n            continue\n        # 多行脚本块\n        bm = re.match(r\'^\\[(shell|cmd|powershell|ps|shellx|psx)\\]\\s*$\', t, re.I)\n        if bm:\n            tag = bm.group(1).lower()\n            block = []\n            end_tag = {\'shell\': \'[/shell]\', \'cmd\': \'[/cmd]\', \'powershell\': \'[/powershell]\', \'ps\': \'[/powershell]\',\n                       \'shellx\': \'[/shellx]\', \'psx\': \'[/psx]\'}[tag]\n            while i < len(lines) and lines[i].strip() != end_tag:\n                block.append(lines[i])\n                i += 1\n            i += 1  # skip end tag\n            try:\n                _run_block(tag, \'\\n\'.join(block), log)\n            except Exception as e:\n                fails += 1\n                log(\'块执行失败: %s\' % e)\n            continue\n        sp = t.find(\' \')\n        verb = (t[:sp] if sp > 0 else t).lower()\n        arg = t[sp + 1:].strip() if sp > 0 else \'\'\n        # ② 破坏性动词: 执行前确认 (用户拒绝则跳过该步并计入 fail)\n        if verb in DESTRUCTIVE_VERBS and confirm and not confirm(\'插件要执行[%s] %s\\n确定继续?\' % (verb, arg[:50])):\n            fails += 1\n            log(\'确认被拒: %s\' % verb)\n            continue\n        try:\n            fails += _run_verb(verb, arg, log, msgbox, confirm)\n        except Exception as e:\n            fails += 1\n            log(\'%s 失败: %s\' % (verb, e))\n    return fails\n\n\ndef _run_verb(verb, arg, log, msgbox, confirm):\n    if verb == \'msg\':\n        msgbox(\'提示\', os.path.expandvars(arg))\n    elif verb == \'confirm\':\n        if not confirm(os.path.expandvars(arg)):\n            raise RuntimeError(\'user-abort\')\n    elif verb == \'run\':\n        parts = tokenize(arg)\n        if parts:\n            r = subprocess.run(parts, capture_output=True, timeout=120)\n            log(\'run %s -> %s\' % (parts[0], r.returncode))\n    elif verb == \'shell\':\n        r = subprocess.run(\'cmd /c \' + os.path.expandvars(arg), shell=True, capture_output=True, timeout=120)\n        log(\'shell -> %s\' % r.returncode)\n    elif verb == \'shellx\':\n        subprocess.run(\'cmd /c \' + os.path.expandvars(arg), shell=True,\n                       creationflags=subprocess.CREATE_NEW_CONSOLE, timeout=86400)\n    elif verb == \'open\':\n        os.startfile(os.path.expandvars(arg))\n    elif verb == \'kill\':\n        img = arg.replace(\'"\', \'\').replace(\'&\', \'\').replace(\'|\', \'\').replace(\'<\', \'\').replace(\'>\', \'\').replace(\'^\', \'\')\n        if not re.match(r\'^[\\w. -]+$\', img):\n            raise RuntimeError(\'bad image name: %s\' % arg)\n        subprocess.run([\'taskkill\', \'/f\', \'/im\', img + \'.exe\'], capture_output=True, timeout=60)\n    elif verb == \'wait\':\n        time.sleep(int(arg) / 1000.0)\n    elif verb == \'mkdir\':\n        os.makedirs(os.path.expandvars(arg), exist_ok=True)\n    elif verb == \'file-del\':\n        target = os.path.expandvars(arg)\n        base = re.split(r\'[*?\\[]\', target)[0].rstrip(\'\\\\/ \')   # 去掉 glob 元字符后再判根\n        if re.match(r\'^[A-Za-z]:$\', base) or re.match(r\'^\\\\\\\\[^\\\\]+\\\\[^\\\\]+$\', base):\n            raise RuntimeError(\'refuse drive/UNC root\')\n        for p in glob.glob(target):\n            try:\n                if os.path.isdir(p):\n                    shutil.rmtree(p, ignore_errors=True)\n                else:\n                    os.remove(p)\n            except OSError as e:\n                log(\'file-del skip %s: %s\' % (p, e))\n    elif verb == \'reg-set\':\n        parts = tokenize(arg)\n        if len(parts) >= 4:\n            hive, sub = parts[0].split(\'\\\\\', 1)\n            name = None if parts[1] == \'-\' else parts[1]\n            typ = parts[2].lower()\n            data = parts[3]\n            with winreg.CreateKey(REG_HIVES[hive.upper()], sub) as key:   # with 自动 CloseKey, 防句柄泄漏\n                if typ == \'dword\':\n                    winreg.SetValueEx(key, name, 0, winreg.REG_DWORD, int(data, 0))\n                elif typ == \'qword\':\n                    winreg.SetValueEx(key, name, 0, winreg.REG_QWORD, int(data, 0))\n                elif typ == \'expand\':\n                    winreg.SetValueEx(key, name, 0, winreg.REG_EXPAND_SZ, data)\n                elif typ == \'multi\':\n                    winreg.SetValueEx(key, name, 0, winreg.REG_MULTI_SZ, data.split(\'|\'))\n                else:\n                    winreg.SetValueEx(key, name, 0, winreg.REG_SZ, data)\n    elif verb == \'reg-del\':\n        parts = tokenize(arg)\n        if parts:\n            hive, sub = parts[0].split(\'\\\\\', 1)\n            if len(parts) > 1:\n                with winreg.OpenKey(REG_HIVES[hive.upper()], sub, 0, winreg.KEY_SET_VALUE) as key:\n                    winreg.DeleteValue(key, None if parts[1] == \'-\' else parts[1])\n            else:\n                winreg.DeleteKey(REG_HIVES[hive.upper()], sub)\n    else:\n        log(\'未知动词: %s\' % verb)\n        return 1\n    return 0\n\n\ndef _run_block(tag, content, log):\n    visible = tag in (\'shellx\', \'psx\')\n    if tag in (\'shell\', \'cmd\', \'shellx\'):\n        ext, cmdline = \'.cmd\', \'cmd /c\'\n        data = content.encode(\'mbcs\', errors=\'replace\')          # ANSI\n    else:\n        ext, cmdline = \'.ps1\', \'powershell.exe -NoProfile -ExecutionPolicy Bypass -File\'\n        data = b\'\\xef\\xbb\\xbf\' + content.encode(\'utf-8\')         # UTF-8 BOM\n    fd, path = tempfile.mkstemp(suffix=ext, prefix=\'wgpy-\')\n    with os.fdopen(fd, \'wb\') as f:\n        f.write(data)\n    try:\n        if visible:\n            cmd = \'cmd /c start "wgpy" /wait cmd /k "%s & echo. & echo [按任意键关闭] & pause>nul"\' % path if ext == \'.cmd\' \\\n                else \'cmd /c start "wgpy" /wait cmd /k "%s %s & echo. & echo [按任意键关闭] & pause>nul"\' % (cmdline, path)\n            subprocess.run(cmd, shell=True, timeout=86400)\n        else:\n            r = subprocess.run(\'%s "%s"\' % (cmdline, path), shell=True, capture_output=True, timeout=300)\n            log(\'block -> %s\' % r.returncode)\n    finally:\n        try:\n            os.remove(path)\n        except OSError:\n            pass\n', 'ui': '# -*- coding: utf-8 -*-\n"""ui.py — 纯 Python 版的设计系统 (对齐 docs/WGIME_窗体设计语言.md):\n浅蓝灰底 #E8EDF5 + 白卡片 + 深色控制台 + 圆角 (SetWindowRgn) + 自绘标题栏 + 显式坐标.\n"""\nimport ctypes\nimport tkinter as tk\nimport tkinter.font as tkfont\n\n# 色板 (直接抄规范)\nBG = \'#E8EDF5\'\nHEADER = \'#DCE3EF\'\nCARD = \'#FFFFFF\'\nSURF2 = \'#D9E0EC\'\nBORDER = \'#C3CCDD\'\nTEXT = \'#1D1D1F\'\nSUB = \'#6E7485\'\nACCENT = \'#007AFF\'\nCONBG = \'#2E3040\'\nCONFG = \'#D6D9E2\'\nGREEN = \'#34C759\'\nORANGE = \'#FF9500\'\nBLUE = \'#30B0C7\'\nRED = \'#FF375F\'\n\nFONT_NAMES = [\'Segoe UI Variable Display\', \'Segoe UI\', \'Microsoft YaHei UI\']\n\n\ndef font(size, bold=False, mono=False):\n    if mono:\n        return (\'Consolas\', int(size))\n    # 检测系统实际可用字体(避免 tkinter 静默替换为空 / 修复原 try/except 永不触发的死代码)\n    try:\n        fams = set(tkfont.families(tk._default_root)) if getattr(tk, \'_default_root\', None) else set()\n    except Exception:\n        fams = set()\n    for n in FONT_NAMES:\n        if not fams or n in fams:\n            return (n, int(round(size)), \'bold\' if bold else \'normal\')\n    return (\'Microsoft YaHei UI\', int(round(size)), \'bold\' if bold else \'normal\')\n\n\ndef _round_region(win, w, h):\n    """GDI 原生 Rgn 圆角 (C# 同款, 角落无锯齿)."""\n    try:\n        hwnd = win.winfo_id()\n        gdi32 = ctypes.windll.gdi32\n        user32 = ctypes.windll.user32\n        gdi32.CreateRoundRectRgn.restype = ctypes.c_void_p\n        gdi32.CreateRoundRectRgn.argtypes = [ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int]\n        gdi32.DeleteObject.argtypes = [ctypes.c_void_p]\n        user32.SetWindowRgn.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int]\n        user32.SetWindowRgn.restype = ctypes.c_int\n        rgn = gdi32.CreateRoundRectRgn(0, 0, w + 1, h + 1, 20, 20)\n        if not user32.SetWindowRgn(hwnd, rgn, True):\n            gdi32.DeleteObject(rgn)   # 失败: 释放句柄, 防泄漏\n    except Exception:\n        pass\n\n\ndef center(win, w, h):\n    sw = win.winfo_screenwidth()\n    sh = win.winfo_screenheight()\n    win.geometry(\'%dx%d+%d+%d\' % (w, h, (sw - w) // 2, (sh - h) // 2))\n\n\ndef make_window(title, w, h, on_close=None):\n    """无边框圆角 + 自绘标题栏 + 显式坐标. 返回 (win, content_frame)."""\n    win = tk.Toplevel(tk._default_root)\n    win.overrideredirect(True)\n    win.attributes(\'-topmost\', True)\n    win.configure(bg=BG)\n    center(win, w, h)\n\n    # 标题栏\n    bar = tk.Frame(win, bg=HEADER, height=38)\n    bar.place(x=0, y=0, width=w, height=38)\n    ttl = tk.Label(bar, text=title, bg=HEADER, fg=TEXT, font=font(10, bold=True))\n    ttl.place(x=12, y=9)\n    tk.Frame(bar, bg=BORDER, height=1).place(x=0, y=37, width=w, height=1)\n\n    def close(_=None):\n        try:\n            if on_close:\n                on_close()\n        finally:\n            win.destroy()   # 保证窗口一定销毁(即使 on_close 抛异常)\n\n    xbtn = tk.Label(bar, text=\'✕\', bg=HEADER, fg=TEXT, font=font(11), cursor=\'hand2\')\n    xbtn.place(x=w - 34, y=7, width=26, height=24)\n    xbtn.bind(\'<Button-1>\', close)\n    xbtn.bind(\'<Enter>\', lambda e: xbtn.configure(bg=RED, fg=\'white\'))\n    xbtn.bind(\'<Leave>\', lambda e: xbtn.configure(bg=HEADER, fg=TEXT))\n\n    # 拖动\n    drag = {\'x\': 0, \'y\': 0}\n\n    def start(e):\n        drag[\'x\'], drag[\'y\'] = e.x_root - win.winfo_x(), e.y_root - win.winfo_y()\n\n    def move(e):\n        win.geometry(\'+%d+%d\' % (e.x_root - drag[\'x\'], e.y_root - drag[\'y\']))\n    bar.bind(\'<ButtonPress-1>\', start)\n    bar.bind(\'<B1-Motion>\', move)\n    ttl.bind(\'<ButtonPress-1>\', start)      # 标题文字也能拖动(tkinter 事件不向父冒泡)\n    ttl.bind(\'<B1-Motion>\', move)\n\n    # 内容区\n    content = tk.Frame(win, bg=BG)\n    content.place(x=0, y=38, width=w, height=h - 38)\n\n    # 圆角 (映射后)\n    win.update_idletasks()\n    _round_region(win, w, h)\n    win.bind(\'<Escape>\', lambda e: close())\n    win.configure(width=w, height=h)\n    return win, content\n\n\ndef flat_button(parent, text, command, primary=False, x=0, y=0, w=90, h=32):\n    """扁平按钮: 白卡, primary=accent 实心白字. hover 提亮/按下压暗."""\n    bg = ACCENT if primary else CARD\n    fg = \'white\' if primary else TEXT\n    btn = tk.Label(parent, text=text, bg=bg, fg=fg, font=font(9.5), cursor=\'hand2\')\n    btn.place(x=x, y=y, width=w, height=h)\n\n    def center_text():\n        btn.configure(anchor=\'center\')\n    center_text()\n\n    def enter(_):\n        btn.configure(bg=\'#2C92FF\' if primary else SURF2)\n\n    def leave(_):\n        btn.configure(bg=bg)\n\n    def press(_):\n        btn.configure(bg=\'#0A6CDC\' if primary else SURF2)\n\n    def release(_):\n        btn.configure(bg=bg)\n        command()\n    btn.bind(\'<Enter>\', enter)\n    btn.bind(\'<Leave>\', leave)\n    btn.bind(\'<ButtonPress-1>\', press)\n    btn.bind(\'<ButtonRelease-1>\', release)\n    return btn\n\n\ndef console_text(parent, x=0, y=0, w=400, h=200):\n    """深色控制台 Text (Consolas, 深色底)."""\n    tb = tk.Text(parent, font=font(9.5, mono=True), bg=CONBG, fg=CONFG,\n                 bd=0, highlightthickness=0, wrap=\'none\')\n    tb.place(x=x, y=y, width=w, height=h)\n    return tb\n\n\ndef rounded_entry(parent, x=0, y=0, w=200, h=32, initial=\'\'):\n    """圆角白底输入框 (Frame 容器 + 内嵌无边框 Entry)."""\n    frame = tk.Frame(parent, bg=CARD, highlightthickness=1, highlightbackground=BORDER)\n    frame.place(x=x, y=y, width=w, height=h)\n    e = tk.Entry(frame, font=font(9.5), bg=CARD, fg=TEXT, bd=0, highlightthickness=0)\n    e.place(x=9, y=4, width=w - 18, height=h - 8)\n    if initial:\n        e.insert(0, initial)\n    return e\n', 'tools': '# -*- coding: utf-8 -*-\n"""tools.py — 纯 tkinter 内置工具窗体, 遵循 docs/WGIME_窗体设计语言.md (浅蓝灰底+白卡片+深色控制台+圆角)."""\nimport os\nimport threading\nimport time\nimport tkinter as tk\nfrom tkinter import messagebox\n\nimport plugins as plugmod\nimport win as w32\nimport ui\n\n\ndef _bg(fn):\n    threading.Thread(target=fn, daemon=True).start()\n\n\ndef _msgbox(title, text):\n    """线程安全弹窗: 后台线程调用经 tk default root marshal 回主线程."""\n    try:\n        r = getattr(tk, \'_default_root\', None)\n        if r:\n            r.after(0, lambda: messagebox.showinfo(title, text))\n        else:\n            messagebox.showinfo(title, text)\n    except Exception:\n        pass\n\n\ndef _confirm(text):\n    """线程安全确认: 主线程 askyesno, 后台线程阻塞等待结果."""\n    ev = threading.Event()\n    res = [False]\n    try:\n        r = getattr(tk, \'_default_root\', None)\n        if r:\n            def ask():\n                try:\n                    res[0] = messagebox.askyesno(\'确认\', text)\n                except Exception:\n                    pass\n                ev.set()\n            r.after(0, ask)\n            ev.wait()\n        else:\n            return messagebox.askyesno(\'确认\', text)\n    except Exception:\n        return False\n    return res[0]\n\n\n# ---------- 工具箱 (tools.txt tab/按钮 -> 步骤 DSL; 自绘标签页) ----------\ndef show_toolbox(tools, dict_dir):\n    if not tools:\n        _msgbox(\'工具箱\', \'tools.txt 无内容\')\n        return\n    win, content = ui.make_window(\'WgIme 工具箱\', 520, 420)\n    W, H = 520, 420\n    tabbar = tk.Frame(content, bg=ui.BG)\n    tabbar.place(x=10, y=8, width=W - 20, height=34)\n    body = tk.Frame(content, bg=ui.BG)\n    body.place(x=10, y=48, width=W - 20, height=H - 48 - 14)\n    pages = []\n    tabbtns = []\n\n    def show_tab(i):\n        for j, p in enumerate(pages):\n            p.place_forget()\n        pages[i].place(x=0, y=0, width=W - 20, height=H - 62)\n        for j, b in enumerate(tabbtns):\n            b.configure(fg=ui.ACCENT if j == i else ui.SUB)\n\n    for i, tab in enumerate(tools):\n        tb = ui.flat_button(tabbar, tab[\'name\'], (lambda i=i: show_tab(i)), x=i * 92, y=0, w=84, h=28)\n        tabbtns.append(tb)\n        page = tk.Frame(body, bg=ui.BG)\n        cols = max(1, min(6, tab.get(\'cols\', 2)))\n        btns = tab[\'buttons\']\n        for bi, b in enumerate(btns):\n            bw = (W - 20 - (cols - 1) * 8) // cols\n            btn = ui.flat_button(page, b[\'name\'], (lambda s=\'\\n\'.join(b[\'steps\']): _run_tool_steps(s)),\n                                 x=(bi % cols) * (bw + 8), y=(bi // cols) * 46, w=bw, h=38)\n        pages.append(page)\n    show_tab(0)\n\n\ndef _run_tool_steps(steps):\n    """后台线程执行工具步骤, msgbox/confirm 经 marshal 回主线程, 不阻塞工具箱/输入法."""\n    def work():\n        try:\n            fails = plugmod.run_steps(steps, lambda m: print(\'[tool]\', m), _msgbox, _confirm)\n            if fails:\n                _msgbox(\'工具箱\', \'部分步骤失败 (%d)\' % fails)\n        except Exception as ex:\n            _msgbox(\'工具箱\', \'失败: %s\' % ex)\n    threading.Thread(target=work, daemon=True).start()\n\n\n# ---------- 剪贴板历史 ----------\n_CLIPT = []\n_clip_started = [False]\n\n\ndef _clip_poll():\n    last = None\n    while True:                                        # daemon 线程, 进程退出自动停\n        time.sleep(1.0)\n        try:\n            t = w32.clipboard_text()\n            if t and t != last:\n                last = t\n                if not _CLIPT or _CLIPT[0] != t:\n                    _CLIPT.insert(0, t)\n                    del _CLIPT[30:]\n        except Exception:\n            pass\n\n\ndef show_clipboard():\n    if not _clip_started[0]:                            # 守卫: 轮询线程只启动一次(防多开叠加)\n        _clip_started[0] = True\n        _bg(_clip_poll)\n    win, content = ui.make_window(\'WgIme 剪贴板历史\', 420, 400)\n    lst = tk.Listbox(content, font=ui.font(9.5), bg=ui.CARD, fg=ui.TEXT, bd=0,\n                     highlightthickness=1, highlightbackground=ui.BORDER, selectbackground=ui.ACCENT)\n    lst.place(x=10, y=10, width=400, height=320)\n\n    def refresh():\n        lst.delete(0, \'end\')\n        for t in _CLIPT:\n            lst.insert(\'end\', t.replace(\'\\r\', \' \').replace(\'\\n\', \' \')[:60])\n\n    def copy():\n        i = lst.curselection()\n        if i and 0 <= i[0] < len(_CLIPT):\n            win.clipboard_clear()\n            win.clipboard_append(_CLIPT[i[0]])\n\n    def paste():\n        i = lst.curselection()\n        if i and 0 <= i[0] < len(_CLIPT):\n            win.clipboard_clear()\n            win.clipboard_append(_CLIPT[i[0]])\n            _bg(lambda: (time.sleep(0.12), w32.paste_text(_CLIPT[i[0]])))\n    ui.flat_button(content, \'复制选中\', copy, x=10, y=342, w=90, h=30)\n    ui.flat_button(content, \'粘贴上屏\', paste, primary=True, x=110, y=342, w=90, h=30)\n    ui.flat_button(content, \'刷新\', refresh, x=210, y=342, w=70, h=30)\n    refresh()\n\n\n# ---------- 便签 ----------\ndef show_notes(data_dir):\n    win, content = ui.make_window(\'WgIme 便签\', 420, 320)\n    path = os.path.join(data_dir, \'notes.txt\')\n    frame = tk.Frame(content, bg=ui.CARD, highlightthickness=1, highlightbackground=ui.BORDER)\n    frame.place(x=10, y=10, width=400, height=270)\n    tb = tk.Text(frame, font=ui.font(11), bg=ui.CARD, fg=ui.TEXT, bd=0, highlightthickness=0,\n                 padx=8, pady=8, wrap=\'word\')\n    tb.pack(fill=\'both\', expand=True)\n    try:\n        tb.insert(\'1.0\', open(path, encoding=\'utf-8\').read())\n    except OSError:\n        pass\n    win.protocol(\'WM_DELETE_WINDOW\', lambda: (_save(tb, path), win.destroy()))\n\n\ndef _save(tb, path):\n    try:\n        open(path, \'w\', encoding=\'utf-8\').write(tb.get(\'1.0\', \'end\'))\n    except OSError:\n        pass\n\n\n# ---------- 取色器 ----------\ndef show_color():\n    win, content = ui.make_window(\'WgIme 取色器\', 220, 200)\n    prev = tk.Frame(content, bg=\'#000\')\n    prev.place(x=10, y=10, width=200, height=120)\n    lbl = tk.Label(content, text=\'\', bg=ui.BG, fg=ui.TEXT, font=ui.font(12, bold=True))\n    lbl.place(x=10, y=138, width=200, height=24)\n    state = {\'hex\': \'#000000\'}\n\n    def tick():\n        x, y = w32.cursor_pos()\n        if win.winfo_x() <= x <= win.winfo_x() + win.winfo_width() and win.winfo_y() <= y <= win.winfo_y() + win.winfo_height():\n            win.after(60, tick)     # 光标在窗口内: 跳过采样但保持调度链, 否则移出后不再取色\n            return\n        px = w32.get_pixel(x, y)\n        if px is None:\n            win.after(60, tick)     # 取色失败(越屏/无DC): 跳过本次, 保持调度\n            return\n        r, g, b = px\n        state[\'hex\'] = \'#%02X%02X%02X\' % (r, g, b)\n        prev.configure(bg=state[\'hex\'])\n        lbl.config(text=\'%s  (%d,%d)\' % (state[\'hex\'], x, y))\n        win.after(60, tick)\n\n    def copy(_):\n        win.clipboard_clear()\n        win.clipboard_append(state[\'hex\'])\n        lbl.config(text=\'已复制 \' + state[\'hex\'])\n    prev.bind(\'<Button-1>\', copy)\n    lbl.bind(\'<Button-1>\', copy)\n    tick()\n\n\n# ---------- 网络工具 (7 页签: Ping/Tracert/DNS/HTTP/端口/子网/本机) ----------\ndef show_nettools():\n    win, content = ui.make_window(\'WgIme 网络工具\', 640, 420)\n    W, H = 640, 420\n    out = ui.console_text(content, x=12, y=88, w=W - 24, h=H - 88 - 12)\n\n    def log(s):\n        win.after(0, lambda: (out.insert(\'end\', s + \'\\n\'), out.see(\'end\')))\n\n    def run_bg(fn):\n        _bg(fn)\n\n    # 页签\n    pages = []\n    names = [\'Ping\', \'Tracert\', \'DNS\', \'HTTP\', \'端口\', \'子网\', \'本机\']\n    tbs = []\n\n    def show_tab(i):\n        for j, p in enumerate(pages):\n            pass\n        for j, b in enumerate(tbs):\n            b.configure(fg=ui.ACCENT if j == i else ui.SUB)\n        run_tab(i)\n\n    def run_tab(i):\n        out.delete(\'1.0\', \'end\')\n        run_bg(lambda: _run_page(i))\n\n    chipw = (W - 24) // len(names)\n    for i, n in enumerate(names):\n        b = ui.flat_button(content, n, (lambda i=i: show_tab(i)), x=12 + i * chipw, y=12, w=chipw - 4, h=28)\n        tbs.append(b)\n    # host 输入框 (页签下方)\n    host = ui.rounded_entry(content, x=12, y=48, w=300, h=30, initial=\'www.baidu.com\')\n\n    def _run_page(i):\n        h = host.get().strip()\n        try:\n            if i == 0:\n                _shell(\'ping -n 4 \' + h)\n            elif i == 1:\n                _shell(\'tracert -d \' + h)\n            elif i == 2:\n                _shell(\'nslookup \' + h)\n            elif i == 3:\n                _http(h)\n            elif i == 4:\n                _ports(h)\n            elif i == 5:\n                _subnet()\n            elif i == 6:\n                _local()\n        except Exception as ex:\n            log(\'ERR %s\' % ex)\n\n    def _shell(cmd):\n        log(\'> \' + cmd)\n        p = __import__(\'subprocess\').Popen(cmd, shell=True, stdout=-1, stderr=-1, universal_newlines=True)\n        for line in p.stdout:\n            log(line.rstrip(\'\\n\'))\n        p.stdout.close()\n        p.wait()\n        log(\'-- done --\')\n\n    def _http(h):\n        import urllib.request\n        url = h if h.startswith(\'http\') else \'https://\' + h\n        log(\'> GET \' + url)\n        req = urllib.request.Request(url, headers={\'User-Agent\': \'WgIme-Py-NetTools\'})\n        t0 = time.time()\n        try:\n            with urllib.request.urlopen(req, timeout=10) as r:\n                log(\'HTTP %s  %dms\' % (r.status, int((time.time() - t0) * 1000)))\n                log(\'Server: %s\' % r.headers.get(\'Server\', \'-\'))\n                log(\'Content-Type: %s\' % r.headers.get(\'Content-Type\', \'-\'))\n        except Exception as ex:\n            log(\'ERR %s\' % ex)\n\n    def _ports(h):\n        import socket as _s\n        log(\'> 端口探测 %s\' % h)\n        for port in (80, 443, 22, 21, 25, 3306, 3389, 8080):\n            try:\n                s = _s.create_connection((h, port), timeout=2)\n                s.close()\n                log(\'%d 开放\' % port)\n            except Exception:\n                log(\'%d 关闭\' % port)\n\n    def _subnet():\n        import socket as _s\n        log(\'> 子网信息\')\n        try:\n            hn = _s.gethostname()\n            log(\'主机名: %s\' % hn)\n            for info in _s.getaddrinfo(hn, None, _s.AF_INET):\n                log(\'IP: %s\' % info[4][0])\n        except Exception as ex:\n            log(\'ERR %s\' % ex)\n\n    def _local():\n        import socket as _s\n        log(\'> 本机信息\')\n        log(\'主机名: %s\' % _s.gethostname())\n        try:\n            log(\'内网IP: %s\' % _s.gethostbyname(_s.gethostname()))\n        except Exception:\n            pass\n        try:\n            import urllib.request\n            ip = urllib.request.urlopen(\'https://api.ipify.org\', timeout=5).read().decode()\n            log(\'公网IP: %s\' % ip)\n        except Exception:\n            log(\'公网IP: (获取失败)\')\n\n    show_tab(0)\n\n\n# ---------- 造词对话框 ----------\ndef show_makeword(data_dir, engine, prefill=\'\'):\n    win, content = ui.make_window(\'WgIme 造词\', 380, 200)\n    tk.Label(content, text=\'词语 (2-8 字)\', bg=ui.BG, fg=ui.SUB, font=ui.font(8.5)).place(x=14, y=10)\n    wentry = ui.rounded_entry(content, x=14, y=30, w=352, h=32, initial=prefill)\n    tk.Label(content, text=\'编码 (留空自动推导)\', bg=ui.BG, fg=ui.SUB, font=ui.font(8.5)).place(x=14, y=68)\n    centry = ui.rounded_entry(content, x=14, y=88, w=352, h=32)\n    status = tk.Label(content, text=\'\', bg=ui.BG, fg=ui.SUB, font=ui.font(8.5))\n    status.place(x=14, y=126)\n\n    def autofill(*_a):\n        if not centry.get().strip():\n            c = engine.code_for(wentry.get().strip())\n            if c:\n                centry.delete(0, \'end\')\n                centry.insert(0, c)\n    wentry.bind(\'<KeyRelease>\', autofill)\n    autofill()\n\n    def do_make():\n        w = wentry.get().strip()\n        c = centry.get().strip()\n        if not (2 <= len(w) <= 8):\n            status.config(text=\'词语需 2-8 字\', fg=ui.RED)\n            return\n        if not c:\n            c = engine.code_for(w)\n        if not c:\n            status.config(text=\'无法推导编码\', fg=ui.RED)\n            return\n        if engine.add_user_word(w, c):\n            status.config(text=\'已造词: %s (%s)\' % (w, c), fg=ui.GREEN)\n            win.after(900, win.destroy)\n        else:\n            status.config(text=\'已存在: %s\' % w, fg=ui.RED)\n    ui.flat_button(content, \'造词\', do_make, primary=True, x=14, y=152, w=100, h=32)\n    ui.flat_button(content, \'取消\', win.destroy, x=120, y=152, w=90, h=32)\n    wentry.focus_set()\n\n\n# ---------- 插件管理 ----------\ndef show_plugin_mgr(plugins, data_dir, reload_fn):\n    win, content = ui.make_window(\'WgIme 插件管理\', 400, 320)\n    frame = tk.Frame(content, bg=ui.BG)\n    frame.place(x=12, y=10, width=376, height=270)\n    vars_ = []\n    try:\n        disabled = set(l.strip() for l in open(os.path.join(data_dir, \'plugins-disabled.txt\'), encoding=\'utf-8\') if l.strip())\n    except OSError:\n        disabled = set()\n    pmap = {\'network\': \'联网\', \'run\': \'执行命令\', \'registry\': \'注册表\', \'destructive\': \'破坏\'}\n    for m in plugins:\n        code = getattr(m, \'CODE\', \'?\')\n        name = getattr(m, \'NAME\', code)\n        ver = str(getattr(m, \'VERSION\', \'\') or \'\')\n        aut = str(getattr(m, \'AUTHOR\', \'\') or \'\')\n        perm = str(getattr(m, \'PERM\', \'low\') or \'low\')\n        info = (\' [v%s%s]\' % (ver, (\'@\' + aut) if aut else \'\')) if ver else ((\' [\' + aut + \']\') if aut else \'\')\n        risk = (\'  ⚠%s\' % pmap.get(perm, perm)) if perm in pmap else \'\'\n        v = tk.BooleanVar(value=(code not in disabled))\n        cb = tk.Checkbutton(frame, text=\'%s (%s)%s%s  %s\' % (name, code, info, risk, getattr(m, \'DESC\', \'\')), variable=v,\n                            anchor=\'w\', bg=ui.BG, fg=ui.TEXT, font=ui.font(9.5), activebackground=ui.BG)\n        cb.pack(fill=\'x\')\n        vars_.append((code, v))\n\n    def apply():\n        dis = set(code for code, v in vars_ if not v.get())\n        try:\n            open(os.path.join(data_dir, \'plugins-disabled.txt\'), \'w\', encoding=\'utf-8\').write(\'\\n\'.join(sorted(dis)))\n        except OSError:\n            pass\n        reload_fn()\n        _msgbox(\'插件管理\', \'已应用并重载\')\n    ui.flat_button(content, \'应用\', apply, primary=True, x=12, y=282, w=90, h=30)\n\n\n# ---------- 导入码表 (转换常见码表 -> import_py/wb/ec.txt) ----------\ndef _import_dialog(target, detected):\n    """目标(五笔/拼音/英汉) + 格式(自动/词在前/码在前)确认; 返回 (target, fmt) 或 None."""\n    import engine as engmod\n    win = tk.Toplevel()\n    win.title(\'导入码表\')\n    win.attributes(\'-topmost\', True)\n    win.resizable(False, False)\n    win.configure(bg=ui.BG)\n    result = {\'target\': target, \'fmt\': 0, \'cancel\': False}\n\n    tk.Label(win, text=\'目标词库\', bg=ui.BG, fg=ui.TEXT, font=ui.font(9.5)).grid(\n        row=0, column=0, columnspan=3, sticky=\'w\', padx=14, pady=(12, 2))\n    tvar = tk.IntVar(value=target)\n    for i, n in enumerate((\'五笔\', \'拼音\', \'英汉\')):\n        tk.Radiobutton(win, text=n, variable=tvar, value=i, bg=ui.BG, fg=ui.TEXT,\n                       selectcolor=ui.BG, activebackground=ui.BG, font=ui.font(9.5)).grid(\n            row=1, column=i, padx=10, pady=4)\n\n    tk.Label(win, text=\'格式\', bg=ui.BG, fg=ui.TEXT, font=ui.font(9.5)).grid(\n        row=2, column=0, columnspan=3, sticky=\'w\', padx=14, pady=(10, 2))\n    fvar = tk.IntVar(value=0)\n    for i, (n, v) in enumerate(((\'自动\', 0), (\'词在前\', 1), (\'码在前\', 2))):\n        tk.Radiobutton(win, text=n, variable=fvar, value=v, bg=ui.BG, fg=ui.TEXT,\n                       selectcolor=ui.BG, activebackground=ui.BG, font=ui.font(9.5)).grid(\n            row=3, column=i, padx=10, pady=4)\n\n    def ok():\n        result[\'target\'] = tvar.get()\n        result[\'fmt\'] = fvar.get()\n        win.destroy()\n\n    def cancel():\n        result[\'cancel\'] = True\n        win.destroy()\n\n    win.protocol(\'WM_DELETE_WINDOW\', cancel)   # 点标题栏 X = 取消(否则被当"确定"导致误导入)\n\n    btns = tk.Frame(win, bg=ui.BG)\n    btns.grid(row=4, column=0, columnspan=3, pady=14)\n    tk.Button(btns, text=\'确定\', command=ok, width=8).pack(side=\'left\', padx=6)\n    tk.Button(btns, text=\'取消\', command=cancel, width=8).pack(side=\'left\', padx=6)\n    win.wait_window()\n    if result[\'cancel\']:\n        return None\n    return result[\'target\'], result[\'fmt\']\n\n\ndef show_import(engine, dict_dir):\n    """导入码表: 选文件 -> 检测 -> 确认 -> 转换写 import_*.txt -> 热重载."""\n    from tkinter import filedialog\n    import engine as engmod\n\n    path = filedialog.askopenfilename(\n        title=\'选择要导入的码表\',\n        filetypes=[(\'码表文件\', \'*.txt *.dict *.yaml *.yml\'), (\'所有文件\', \'*.*\')])\n    if not path:\n        return\n    text = engmod.read_import_text(path)\n    if text is None:\n        _msgbox(\'导入失败\', \'文件超过 64MB 或无法读取\')\n        return\n    detected = engmod.detect_format(text.split(\'\\n\'))\n    target = engmod.suggest_target(os.path.basename(path))\n    r = _import_dialog(target, detected)\n    if r is None:\n        return\n    target, fmt = r\n    if fmt == 0:\n        fmt = detected if detected else 2                      # 自动 -> 检测结果(默认码在前)\n    import_path = os.path.join(dict_dir, (\'import_wb.txt\' if target == 0 else (\'import_py.txt\' if target == 1 else \'import_ec.txt\')))\n    try:\n        acc = engmod.load_import_base(import_path)\n        base_words = sum(len(v) for v in acc.values())\n        skipped, trunc_codes, trunc_total = engmod.convert_file(text, fmt, acc)\n        new_words = sum(len(v) for v in acc.values()) - base_words\n        if new_words <= 0:\n            _msgbox(\'导入\', \'没有新增词条\')\n            return\n        engmod.write_import_file(import_path, acc)\n        engine.reload()\n        _msgbox(\'导入完成\', \'新增 %d 词条 (跳过 %d 行, 截断 %d 码)\' % (new_words, skipped, trunc_codes))\n    except Exception as ex:\n        _msgbox(\'导入失败\', str(ex))\n', 'tray': '# -*- coding: utf-8 -*-\n"""tray.py — pystray 托盘: 启用/禁用, 模式, 繁简, 退出. 回调 marshal 回 tkinter 主线程."""\ntry:\n    import pystray\n    from PIL import Image, ImageDraw, ImageFont\n    HAS_TRAY = True\nexcept Exception:\n    pystray = None\n    HAS_TRAY = False\n\nimport queue\nimport ctypes as _ct\n\n\ndef _is_zh():\n    try:\n        return (_ct.windll.kernel32.GetUserDefaultUILanguage() & 0x3FF) == 0x04   # 主语言 0x04 = 中文\n    except Exception:\n        return True\n\n\n_ZH = _is_zh()\n\n\ndef L(zh, en):\n    """C# 同款: 按系统 UI 语言返回中文或英文."""\n    return zh if _ZH else en\n\n\nMODE_NAMES = (\'混合\', \'拼音\', \'五笔\', \'词典\')\nMODE_EN = (\'Mixed\', \'Pinyin\', \'Wubi\', \'Dict\')\n# 与 C# 版一致: 模式汉字镂空 + Win11 强调色 (中/拼/五/译), 未激活灰\nMODE_CHARS = (\'中\', \'拼\', \'五\', \'译\')\nMODE_COLORS = ((0, 120, 212), (0, 183, 195), (202, 80, 16), (136, 23, 152))\nOFF_COLOR = (190, 185, 179)\n\n# 托盘回调 (pystray 线程) 不能直接碰 tkinter —— 入队, 主线程 poll 里执行\nTRAY_Q = queue.Queue()\n\n\ndef _icon_img(mode, active):\n    """C# 同款: 圆角方形 + 模式汉字镂空 + 模式色."""\n    color = MODE_COLORS[mode % 4] if active else OFF_COLOR\n    img = Image.new(\'RGBA\', (64, 64), (0, 0, 0, 0))\n    d = ImageDraw.Draw(img)\n    d.rounded_rectangle([0, 0, 63, 63], 14, fill=color + (255,))\n    ch = MODE_CHARS[mode % 4]\n    try:\n        font = ImageFont.truetype(\'msyh.ttc\', 52)\n    except Exception:\n        try:\n            font = ImageFont.truetype(\'Microsoft YaHei UI\', 52)\n        except Exception:\n            font = ImageFont.load_default()\n    mask = Image.new(\'L\', (64, 64), 0)\n    md = ImageDraw.Draw(mask)\n    md.text((32, 32), ch, font=font, fill=255, anchor=\'mm\')\n    px = img.load()\n    pm = mask.load()\n    for y in range(64):\n        for x in range(64):\n            if pm[x, y] > 128:\n                px[x, y] = (0, 0, 0, 0)\n    return img\n\n\nclass Tray:\n    def __init__(self, root, api):\n        self.root = root\n        self.api = api\n        self.icon = None\n\n    def _refresh(self):\n        try:\n            self.icon.icon = _icon_img(self.api[\'get_mode\'](), self.api[\'is_active\']())\n            self.icon.update_menu()   # 刷新菜单勾选态(checked 重求值), 否则切换后勾选不变、看起来"没反应"\n        except Exception:\n            pass\n\n    def _on(self, fn):\n        def wrap(_icon, _item):\n            # 入队给主线程执行 (tkinter 不能跨线程调用), 随后刷新图标\n            TRAY_Q.put(lambda: (fn(), self._refresh()))\n        return wrap\n\n    def start(self):\n        if not HAS_TRAY:\n            return False\n        menu = pystray.Menu(\n            # 开关\n            pystray.MenuItem(L(\'开关  (Shift 轻点)\', \'On/Off  (Shift tap)\'), self._on(self.api[\'toggle\'])),\n            pystray.Menu.SEPARATOR,\n            # 模式\n            pystray.MenuItem(L(\'模式  (Ctrl+` 循环)\', \'Mode  (Ctrl+` cycles)\'),\n                             pystray.Menu(\n                                 *(pystray.MenuItem(L(MODE_NAMES[m], MODE_EN[m]),\n                                                    self._on(lambda m=m: self.api[\'set_mode\'](m)),\n                                                    checked=lambda _it, m=m: self.api[\'get_mode\']() == m)\n                                   for m in range(4)))),\n            # 选项\n            pystray.MenuItem(L(\'选项\', \'Options\'),\n                             pystray.Menu(\n                                 pystray.MenuItem(L(\'繁体输出  (Ctrl+Shift+F)\', \'Trad output  (Ctrl+Shift+F)\'),\n                                                  self._on(self.api[\'trad\'])),\n                                 pystray.MenuItem(L(\'反查编码\', \'Reverse code\'),\n                                                  self._on(self.api[\'toggleshowcode\']),\n                                                  checked=lambda _it: self.api[\'get_showcode\']()),\n                                 pystray.MenuItem(L(\'整句输入\', \'Sentence mode\'),\n                                                  self._on(self.api[\'togglesentence\']),\n                                                  checked=lambda _it: self.api[\'get_sentence\']()),\n                                 pystray.MenuItem(L(\'联想\', \'Association\'),\n                                                  self._on(self.api[\'toggleassoc\']),\n                                                  checked=lambda _it: self.api[\'get_assoc\']()),\n                                 pystray.MenuItem(L(\'空闲隐藏\', \'Hide when idle\'),\n                                                  self._on(self.api[\'togglehideidle\']),\n                                                  checked=lambda _it: self.api[\'get_hideidle\']()),\n                                 pystray.MenuItem(L(\'候选窗跟随光标\', \'Candidate board follows caret\'),\n                                                  self._on(self.api[\'followcaret\']),\n                                                  checked=lambda _it: self.api[\'get_followcaret\']()),\n                                 pystray.MenuItem(L(\'主题\', \'Theme\'),\n                                                  pystray.Menu(\n                                                      pystray.MenuItem(L(\'深色\', \'Dark\'),\n                                                                       self._on(lambda: self.api[\'set_theme\'](\'dark\')),\n                                                                       checked=lambda _it: self.api[\'get_theme\']() == \'dark\'),\n                                                      pystray.MenuItem(L(\'浅色\', \'Light\'),\n                                                                       self._on(lambda: self.api[\'set_theme\'](\'light\')),\n                                                                       checked=lambda _it: self.api[\'get_theme\']() == \'light\'))))),\n            # 词库\n            pystray.MenuItem(L(\'词库\', \'Dictionary\'),\n                             pystray.Menu(\n                                 pystray.MenuItem(L(\'造词  (Ctrl+Alt+C)\', \'Make Word  (Ctrl+Alt+C)\'),\n                                                  self._on(self.api[\'makeword\'])),\n                                 pystray.MenuItem(L(\'导入码表…\', \'Import Table…\'),\n                                                  self._on(self.api[\'import_table\'])))),\n            pystray.Menu.SEPARATOR,\n            # 这个程序\n            pystray.MenuItem(L(\'这个程序\', \'This app\'),\n                             pystray.Menu(\n                                 pystray.MenuItem(L(\'改用剪贴板上屏\', \'Paste via clipboard\'),\n                                                  self._on(self.api[\'apppaste\'])),\n                                 pystray.MenuItem(L(\'标点吞字修复\', \'Punct stale-char fix\'),\n                                                  self._on(self.api[\'appkeyfix\'])))),\n            pystray.Menu.SEPARATOR,\n            # 退出\n            pystray.MenuItem(L(\'退出\', \'Exit\'), self._on(self.api[\'quit\'])),\n        )\n        self.icon = pystray.Icon(\'WgIme-Pure\', _icon_img(self.api[\'get_mode\'](), True), \'WgIme-Pure\', menu)\n        self.icon.run_detached()\n        self._refresh()\n        return True\n'}
PLUGIN_SRC = {'calc': '# -*- coding: utf-8 -*-\n"""计算器插件: 安全表达式求值 (设计规范: 圆角 + 白卡显示区 + 磁贴网格)."""\nimport re\nimport tkinter as tk\n\nimport ui\n\nCODE = \'js\'\nNAME = \'计算器\'\nDESC = \'安全表达式计算器\'\nVERSION = \'1.0\'\nAUTHOR = \'ogowoo\'\nPERM = \'low\'\n\nSAFE = re.compile(r\'^[\\d+\\-*/().% ]+$\')\n\n\ndef _eval(expr):\n    if not SAFE.match(expr):\n        return \'仅支持数字+(),%\'\n    try:\n        return str(eval(expr.replace(\'%\', \'/100\'), {\'__builtins__\': {}}, {}))\n    except Exception:\n        return \'错误\'\n\n\ndef run():\n    win, content = ui.make_window(\'WgIme 计算器\', 264, 356)\n    disp = tk.Label(content, text=\'\', anchor=\'e\', bg=ui.CARD, fg=ui.TEXT, font=ui.font(18),\n                    padx=10)\n    disp.place(x=10, y=10, width=244, height=44)\n    disp.configure(highlightthickness=1, highlightbackground=ui.BORDER)\n\n    state = {\'expr\': \'\'}\n\n    def press(t):\n        state[\'expr\'] += t\n        disp.config(text=state[\'expr\'])\n\n    def clear():\n        state[\'expr\'] = \'\'\n        disp.config(text=\'\')\n\n    def calc():\n        r = _eval(state[\'expr\'])\n        disp.config(text=r)\n        state[\'expr\'] = \'\' if r in (\'错误\', \'仅支持数字+(),%\') else r\n\n    keys = [(\'(\', \')\', \'%\', \'C\'),\n            (\'7\', \'8\', \'9\', \'/\'),\n            (\'4\', \'5\', \'6\', \'*\'),\n            (\'1\', \'2\', \'3\', \'-\'),\n            (\'0\', \'.\', \'=\', \'+\')]\n    bw = 56\n    bh = 46\n    x0, y0 = 10, 62\n    for r, row in enumerate(keys):\n        for c, k in enumerate(row):\n            if k == \'C\':\n                cmd = clear\n            elif k == \'=\':\n                cmd = calc\n            else:\n                cmd = (lambda t=k: press(t))\n            primary = (k == \'=\')\n            ui.flat_button(content, k, cmd, primary=primary,\n                           x=x0 + c * (bw + 6), y=y0 + r * (bh + 6), w=bw, h=bh)\n    win.bind(\'<Return>\', lambda e: calc())\n    win.bind(\'<BackSpace>\', lambda e: (state.__setitem__(\'expr\', state[\'expr\'][:-1]), disp.config(text=state[\'expr\'])))\n', 'chat': '# -*- coding: utf-8 -*-\n"""纯 Python chat 插件 (relay + MQTT-over-WS, AES-256-CBC 加密, 与 itools-chat 互通).\nCODE=\'lt\', NAME=\'聊天\'. run() 在 tkinter 主线程建窗口, 网络走后台线程, UI 经队列回主线程.\n"""\nimport hashlib\nimport hmac\nimport os\nimport queue\nimport re\nimport socket\nimport ssl\nimport struct\nimport threading\nimport time\nimport tkinter as tk\n\nimport wspy\n\nCODE = \'lt\'\nNAME = \'聊天\'\nDESC = \'与 itools-chat (PC/Android) 互通的在线聊天 (纯 Python)\'\n\nBROKERS = [\'wss://chat.seee.uno\', \'wss://broker.hivemq.com:8884\', \'wss://broker.emqx.io:8084\',\n           \'wss://test.mosquitto.org:8081\', \'ws://broker.hivemq.com:8000\']\nTOPIC = \'itools/chat/\'\n\n\n# ---------- AES-256-CBC + HMAC-SHA256 (与 itools-chat 字节兼容) ----------\nclass Crypto:\n    def __init__(self, room, key):\n        raw = room + \':\' + (key or room)\n        self.k = hashlib.sha256(raw.encode(\'utf-8\')).digest()\n\n    def enc(self, plain):\n        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes\n        from cryptography.hazmat.primitives import padding\n        iv = os.urandom(16)\n        pad = padding.PKCS7(128).padder()\n        pt = pad.update(plain.encode(\'utf-8\')) + pad.finalize()\n        c = Cipher(algorithms.AES(self.k), modes.CBC(iv)).encryptor()\n        ct = c.update(pt) + c.finalize()\n        ivh, cth = iv.hex(), ct.hex()\n        mac = hmac.new(self.k, (ivh + \':\' + cth).encode(\'utf-8\'), hashlib.sha256).hexdigest()\n        return ivh + \':\' + cth + \':\' + mac\n\n    def dec(self, data):\n        from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes\n        from cryptography.hazmat.primitives import padding\n        try:\n            p = data.split(\':\')\n            if len(p) < 3:\n                return None\n            expect = hmac.new(self.k, (p[0] + \':\' + p[1]).encode(\'utf-8\'), hashlib.sha256).hexdigest()\n            if expect != p[2]:\n                return None\n            iv, ct = bytes.fromhex(p[0]), bytes.fromhex(p[1])\n            c = Cipher(algorithms.AES(self.k), modes.CBC(iv)).decryptor()\n            unp = padding.PKCS7(128).unpadder()\n            return (unp.update(c.update(ct) + c.finalize()) + unp.finalize()).decode(\'utf-8\')\n        except Exception:\n            return None\n\n\n# ---------- MQTT 3.1.1 framing (QoS0) ----------\ndef _mq_str(s):\n    b = s.encode(\'utf-8\')\n    return struct.pack(\'>H\', len(b)) + b\n\n\ndef _mq_frame(typ, body):\n    rem = len(body)\n    h = bytearray([typ])\n    while True:\n        b = rem % 128\n        rem //= 128\n        if rem > 0:\n            b |= 0x80\n        h.append(b)\n        if rem == 0:\n            break\n    return bytes(h) + body\n\n\ndef _mq_connect(cid):\n    return _mq_frame(0x10, _mq_str(\'MQTT\') + bytes([4, 2, 0, 30]) + _mq_str(cid))\n\n\ndef _mq_subscribe(pid, topic):\n    return _mq_frame(0x82, struct.pack(\'>H\', pid) + _mq_str(topic) + b\'\\x00\')\n\n\ndef _mq_publish(topic, payload):\n    return _mq_frame(0x30, _mq_str(topic) + payload)\n\n\n# ---------- 插件入口 ----------\n_current = None\n\n\ndef run():\n    global _current\n    _current = ChatUI()\n    _current.start()\n\n\nclass ChatUI:\n    def __init__(self):\n        self.win = None\n        self.q = queue.Queue()\n        self.state = {\'running\': False, \'ws\': None}\n        self.docid = \'py-\' + os.urandom(5).hex()\n        self.last_ts = {}\n        self._sel_broker = BROKERS[0]\n        self._broker_btns = []\n\n    def _on_close(self):\n        """断网(不销毁窗口, 由 make_window 的 close 负责 destroy)."""\n        self.state[\'running\'] = False\n        try:\n            if self.state[\'ws\']:\n                self.state[\'ws\'].close()\n        except Exception:\n            pass\n\n    def _pick_broker(self, i):\n        import ui\n        self._sel_broker = BROKERS[i]\n        for j, b in enumerate(self._broker_btns):\n            b.configure(bg=ui.ACCENT if j == i else ui.CARD, fg=\'white\' if j == i else ui.TEXT)\n\n    # ---- UI (规范风: 浅蓝灰底 + 白卡 + 深色控制台 + 圆角 + 自绘标题栏 + flat 按钮) ----\n    def start(self):\n        import ui\n        w, content = ui.make_window(\'WgIme 聊天\', 520, 460, on_close=self._on_close)   # 无边框圆角+自绘标题栏\n        self.win = w\n        BG, SUB, GREEN = ui.BG, ui.SUB, ui.GREEN\n        # 消息区: 深色控制台\n        self.msg = ui.console_text(content, 10, 8, 500, 240)\n        # 配置行: 昵称 / 房间 / 密钥 (白卡圆角输入)\n        for txt, x in ((\'昵称\', 10), (\'房间\', 140), (\'密钥\', 270)):\n            tk.Label(content, text=txt, bg=BG, fg=SUB, font=ui.font(8.5)).place(x=x, y=254)\n        self.nick = ui.rounded_entry(content, 10, 272, 120, 32, initial=\'User_\' + os.urandom(3).hex())\n        self.room = ui.rounded_entry(content, 140, 272, 120, 32, initial=\'T_Fuck\')\n        self.key = ui.rounded_entry(content, 270, 272, 90, 32)\n        # broker 选择: flat 按钮行 + 加入/离开\n        for i, b in enumerate(BROKERS):\n            nm = b.split(\'//\')[-1].split(\':\')[0].split(\'.\')[0]   # 中继/hivemq/emqx/mosquitto/broker\n            self._broker_btns.append(\n                ui.flat_button(content, nm, (lambda i=i: self._pick_broker(i)), x=10 + i * 84, y=312, w=80, h=30))\n        self._pick_broker(0)\n        self.btn = ui.flat_button(content, \'加入\', self.toggle, primary=True, x=410, y=312, w=92, h=30)\n        # 输入行: 输入框 + 发送\n        self.input = ui.rounded_entry(content, 10, 350, 420, 32)\n        self.input.bind(\'<Return>\', self.send)\n        ui.flat_button(content, \'发送\', self.send, primary=True, x=436, y=350, w=74, h=32)\n        # 状态栏\n        self.status = tk.Label(content, text=\'未连接\', bg=BG, fg=SUB, anchor=\'w\', font=ui.font(8.5))\n        self.status.place(x=10, y=390, width=220, height=20)\n        self.online = tk.Label(content, text=\'在线 0\', bg=BG, fg=GREEN, anchor=\'e\', font=ui.font(8.5))\n        self.online.place(x=390, y=390, width=120, height=20)\n        self._poll_ui()\n        self.users = set()\n\n    def ui(self, fn):\n        self.q.put(fn)\n\n    def _poll_ui(self):\n        try:\n            while True:\n                fn = self.q.get_nowait()\n                fn()\n        except Exception:\n            pass\n        if self.win.winfo_exists():\n            self.win.after(50, self._poll_ui)\n\n    def add_msg(self, text):\n        self.msg.configure(state=\'normal\')\n        self.msg.insert(\'end\', text + \'\\n\')\n        self.msg.configure(state=\'disabled\')\n        self.msg.see(\'end\')\n\n    def set_status(self, s):\n        self.status.config(text=s)\n\n    # ---- connect ----\n    def toggle(self):\n        if self.state[\'running\']:\n            self.leave()\n        else:\n            self.join()\n\n    def join(self):\n        self.state[\'running\'] = True\n        self.btn.config(text=\'离开\')\n        self.docid = \'py-\' + os.urandom(5).hex()\n        # 主线程固化配置 (tkinter 变量跨线程读不安全)\n        self.state[\'nick\'] = self.nick.get().strip() or \'User\'\n        self.state[\'room\'] = self.room.get().strip() or \'T_Fuck\'\n        self.state[\'key\'] = self.key.get().strip()\n        self.state[\'broker\'] = self._sel_broker\n        threading.Thread(target=self._net_loop, daemon=True).start()\n\n    def leave(self):\n        self.state[\'running\'] = False\n        try:\n            if self.state[\'ws\']:\n                self.state[\'ws\'].close()\n        except Exception:\n            pass\n        self.btn.config(text=\'加入\')\n        self.ui(lambda: self.set_status(\'未连接\'))\n\n    def _broker_info(self):\n        url = self.state.get(\'broker\', BROKERS[0])\n        relay = \'chat.seee.uno\' in url\n        return url, relay\n\n    def _net_loop(self):\n        url, relay = self._broker_info()\n        room = self.state[\'room\']\n        nick = self.state[\'nick\']\n        crypto = Crypto(room, self.state[\'key\'])\n        self.ui(lambda: self.set_status(\'连接中…\'))\n        try:\n            full = url.replace(\'/\', \'\', 1) if False else url\n            if relay:\n                ws = wspy.WS()\n                ws.connect(url.rstrip(\'/\') + \'/room/\' + room, subprotocol=None)\n            else:\n                ws = wspy.WS()\n                ws.connect(url.rstrip(\'/\') + \'/mqtt\', subprotocol=\'mqtt\')\n                ws.send_bin(_mq_connect(self.docid))\n            self.state[\'ws\'] = ws\n            if relay:\n                self._send_json(ws, {\'type\': \'join\', \'nick\': nick, \'ts\': int(time.time() * 1000), \'id\': self.docid})\n                self.ui(lambda: self.set_status(\'已连接 (中继)\'))\n                self._recv_loop(ws, relay, room, nick, crypto)\n            else:\n                self._mqtt_handshake(ws, room, nick, crypto)\n                self._recv_loop(ws, relay, room, nick, crypto)\n        except Exception as e:\n            self.ui(lambda: self.set_status(\'连接失败: %s\' % e))\n            self.ui(lambda: self.btn.config(text=\'加入\'))\n            self.state[\'running\'] = False\n\n    def _mqtt_handshake(self, ws, room, nick, crypto):\n        # 等 CONNACK (0x20) 最多 8s\n        deadline = time.time() + 8\n        while time.time() < deadline:\n            try:\n                op, payload = ws.recv_message()\n            except Exception:\n                raise RuntimeError(\'no CONNACK\')\n            self._mq_handle_packet(ws, op, payload, room, nick, crypto, initial=True)\n            if self.state.get(\'joined\'):\n                return\n        raise RuntimeError(\'CONNACK timeout\')\n\n    def _recv_loop(self, ws, relay, room, nick, crypto):\n        while self.state[\'running\']:\n            try:\n                op, payload = ws.recv_message()\n            except Exception:\n                break\n            if relay:\n                if op == wspy.OP_TEXT:\n                    self._handle_json(ws, payload.decode(\'utf-8\'), relay, room, nick, crypto)\n            else:\n                self._mq_handle_packet(ws, op, payload, room, nick, crypto)\n        if self.state[\'running\']:\n            self.ui(lambda: self.set_status(\'已断开\'))\n            self.ui(lambda: self.btn.config(text=\'加入\'))\n            self.state[\'running\'] = False\n\n    def _mq_handle_packet(self, ws, op, payload, room, nick, crypto, initial=False):\n        if op != wspy.OP_BIN:\n            return\n        pos = 0\n        while pos + 2 <= len(payload):\n            head = payload[pos]\n            typ = head & 0xF0\n            i = pos + 1\n            rem = 0\n            shift = 0\n            for _ in range(4):\n                b = payload[i]\n                rem |= (b & 0x7F) << shift\n                shift += 7\n                i += 1\n                if not (b & 0x80):\n                    break\n            if i + rem > len(payload):\n                break\n            body = payload[i:i + rem]\n            if typ == 0x20:                       # CONNACK\n                if body[1] == 0:\n                    self.state[\'joined\'] = True\n                    ws.send_bin(_mq_subscribe(1, TOPIC + room))\n                    self._send_json(ws, {\'type\': \'join\', \'nick\': nick, \'ts\': int(time.time() * 1000), \'id\': self.docid})\n                    self.ui(lambda: self.set_status(\'已连接 (MQTT)\'))\n            elif typ == 0x30:                     # PUBLISH\n                tl = struct.unpack(\'>H\', body[:2])[0]\n                topic = body[2:2 + tl].decode(\'utf-8\')\n                self._handle_json(ws, body[2 + tl:].decode(\'utf-8\'), False, room, nick, crypto)\n            pos = i + rem\n\n    # ---- helpers ----\n    def _send_json(self, ws, obj):\n        s = json_dumps(obj)\n        if ws is None:\n            return\n        if \'chat.seee.uno\' in self.state.get(\'broker\', \'\'):\n            ws.send_text(s)\n        else:\n            ws.send_bin(_mq_publish(TOPIC + self.state.get(\'room\', \'\'), s.encode(\'utf-8\')))\n\n    def send(self, _ev=None):\n        text = self.input.get()\n        if not text.strip():\n            return\n        self.input.delete(0, \'end\')\n        nick = self.nick.get().strip() or \'User\'\n        self.add_msg(\'%s  %s\' % (nick, text))\n        crypto = Crypto(self.room.get().strip(), self.key.get().strip())\n        enc = crypto.enc(text)\n        self._send_json(self.state[\'ws\'], {\'type\': \'chat\', \'nick\': nick, \'text\': enc, \'enc\': True,\n                                           \'ts\': int(time.time() * 1000), \'id\': self.docid})\n\n    def _handle_json(self, ws, raw, relay, room, nick, crypto):\n        try:\n            d = json_loads(raw)\n        except Exception:\n            return\n        t = d.get(\'type\')\n        rid = d.get(\'id\')\n        rnick = d.get(\'nick\')\n        if rid == self.docid:\n            return\n        if t == \'join\':\n            if rnick:\n                self.users.add(rnick)\n                self.ui(lambda: self.add_msg(\'· %s 加入了\' % rnick))\n                self.ui(self._update_online)\n                self._send_json(ws, {\'type\': \'online\', \'nick\': nick, \'ts\': int(time.time() * 1000), \'id\': self.docid})\n        elif t == \'leave\':\n            if rnick:\n                self.users.discard(rnick)\n                self.ui(lambda: self.add_msg(\'· %s 离开了\' % rnick))\n                self.ui(self._update_online)\n        elif t == \'online\':\n            if rnick:\n                self.users.add(rnick)\n                self.ui(self._update_online)\n        elif t == \'chat\':\n            text = crypto.dec(d.get(\'text\', \'\'))\n            if text is None:\n                text = \'[encrypted]\'\n            self.ui(lambda: self.add_msg(\'%s  %s\' % (rnick or \'?\', text)))\n\n    def _update_online(self):\n        self.online.config(text=\'在线 %d\' % len(self.users))\n\n\ndef json_dumps(obj):\n    import json\n    return json.dumps(obj, ensure_ascii=False)\n\n\ndef json_loads(s):\n    import json\n    return json.loads(s)\n', 'clock': '# -*- coding: utf-8 -*-\n"""时钟插件: 置顶时钟 (设计规范: 圆角无边框 + 大数字)."""\nimport datetime\nimport tkinter as tk\n\nimport ui\n\nCODE = \'sk\'\nNAME = \'时钟\'\nDESC = \'置顶时钟\'\n\n\ndef run():\n    win, content = ui.make_window(\'WgIme 时钟\', 240, 130)\n    lbl = tk.Label(content, font=ui.font(34, bold=True), fg=ui.ACCENT, bg=ui.BG, anchor=\'center\')\n    lbl.place(x=0, y=34, width=240, height=52)\n    date = tk.Label(content, font=ui.font(9), fg=ui.SUB, bg=ui.BG, anchor=\'center\')\n    date.place(x=0, y=88, width=240, height=24)\n\n    def tick():\n        now = datetime.datetime.now()\n        lbl.config(text=now.strftime(\'%H:%M:%S\'))\n        date.config(text=now.strftime(\'%Y-%m-%d  %A\'))\n        win.after(1000, tick)\n    tick()\n'}
